    public static void main(String[] args) throws IOException 
    {
        InputReader in=new InputReader(System.in);
        int n=in.nextInt();
        int b=in.nextInt();
        int [] a=new int[n];
        a=in.nextIntArray(n);
        int[] odd=new int[n+1];
        int[] even=new int[n+1];
        odd[0]=0;
        even[0]=0;
        for(int i=1;i<=n;i++)
        {
            if(a[i-1]%2==1)
            {
                odd[i]=odd[i-1]+1;
                even[i]=even[i-1];
            }
            else
            {
                odd[i]=odd[i-1];
                even[i]=even[i-1]+1;
            }
        }
        int prev=0;
        PriorityQueue<Integer> cost=new PriorityQueue<Integer>();
        for(int i=1;i<=n-1;i++)
        {
            int oc=odd[i]-odd[prev];
            int ec=even[i]-even[prev];
            if(oc==ec)
            {
                cost.add((int)Math.abs(a[i]-a[i-1]));
                //System.out.println((int)Math.abs(a[i]-a[i-1]));
                prev=i;
            }
        }
        int sum=0;
        int count=0;
        while(!cost.isEmpty() && sum<=b)
        {
            sum+=cost.peek().intValue();
            cost.poll();
            count++;
        }
        if(count==0)
        {
            System.out.println("0");
        }
        else
        {
            if(cost.isEmpty() && sum<=b)
            {
                System.out.println(count);
            }
            else
            {
                System.out.println(count-1);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int b = Integer.parseInt(firstLine[1]);
        int[] a = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();

        int[] odd = new int[n + 1];
        int[] even = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            if (a[i - 1] % 2 == 1) {
                odd[i] = odd[i - 1] + 1;
                even[i] = even[i - 1];
            } else {
                odd[i] = odd[i - 1];
                even[i] = even[i - 1] + 1;
            }
        }

        int prev = 0;
        PriorityQueue<Integer> cost = new PriorityQueue<>();
        for (int i = 1; i < n; i++) {
            int oc = odd[i] - odd[prev];
            int ec = even[i] - even[prev];
            if (oc == ec) {
                cost.add(Math.abs(a[i] - a[i - 1]));
                prev = i;
            }
        }

        int sum = 0;
        int count = 0;
        while (!cost.isEmpty() && sum + cost.peek() <= b) {
            sum += cost.poll();
            count++;
