                oddPrefix[i] = oddPrefix[i - 1] + 1;
                evenPrefix[i] = evenPrefix[i - 1];
            }
        }

        ArrayList<Integer> cutCosts = new ArrayList<>();
        for (int i = 0; i < totalNumbers - 1; i++) {
            if (evenPrefix[i] == oddPrefix[i]) {
                cutCosts.add(Math.abs(sequence[i] - sequence[i + 1]));
            }
        }

        Collections.sort(cutCosts);
        int accumulatedCost = 0;
        int maxCuts = 0;
        for (int c : cutCosts) {
            if (accumulatedCost + c <= budget) {
                accumulatedCost += c;
                maxCuts++;
            } else {
                break;
            }
        }
        System.out.println(maxCuts);
    }
}

