            }
        }
        for (int i = 1; i <= size; i++) {
            int val = differences.get(i - 1);
            for (int j = 1; j <= w; j++) {
                if (val <= j) {
                    dp[i][j] = Math.max(1 + dp[i - 1][j - val], dp[i - 1][j]);
                } else {
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }
        System.out.println(dp[size][w]);
    }
