    static int gcd(int a, int b) {
      if (b == 0) 
        return a; 
      return gcd(b, a % b);  
    } 

    static int lcm(int a, int b){
        int g = gcd(a,b);
        return a*(b/g);
    }

    static int exponentMod(int A,  int B, int C)  {    
        if (A == 0)  
            return 0;  
        if (B == 0)  
            return 1;    
        long y;  
        if (B % 2 == 0) 
        {  
            y = exponentMod(A, B / 2, C);  
            y = (y * y) % C;  
        }    
        else 
        {  
            y = A % C;  
            y = (y * exponentMod(A, B - 1,  C) % C) % C;  
        }  
        return (int)((y + C) % C);  
    }

    static class FastReader{ 
        BufferedReader br; 
        StringTokenizer st; 

        public FastReader() 
        { 
            br = new BufferedReader(new
                     InputStreamReader(System.in)); 
        } 

        String next() 
        { 
            while (st == null || !st.hasMoreElements()) 
            { 
                try
                { 
                    st = new StringTokenizer(br.readLine()); 
                } 
                catch (IOException  e) 
                { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 

        int nextInt() 
        { 
            return Integer.parseInt(next()); 
        } 

        long nextLong() 
        { 
            return Long.parseLong(next()); 
        } 

        double nextDouble() 
        { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() 
        { 
            String str = ""; 
            try
            { 
                str = br.readLine(); 
            } 
            catch (IOException e) 
            { 
                e.printStackTrace(); 
            } 
            return str; 
        } 
    }    
