        String[] inputNumbers = reader.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(inputNumbers[i]);
        }
        List<Integer> differences = new ArrayList<>();
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount) {
                differences.add(Math.abs(a[i] - a[i + 1]));
            }
        }
        Collections.sort(differences);
        int count = 0;
        for (int diff : differences) {
            if (diff <= B) {
                B -= diff;
                count++;
            } else {
                break;
            }
        }
        writer.println(count);
        writer.flush();
    }
}

