public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        DataOutputStream dos = new DataOutputStream(System.out);
        int n = readInt(dis);
        int B = readInt(dis);
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = readInt(dis);
        }
        int evenCount = 0, oddCount = 0;
        ArrayList<Integer> differences = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount) {
                differences.add(Math.abs(a[i] - a[i + 1]));
            }
        }
        Collections.sort(differences);
        int total = 0, count = 0;
        for (int diff : differences) {
            total += diff;
            if (total > B) break;
            count++;
        }
        writeInt(dos, count);
        dos.flush();
        dis.close();
        dos.close();
    }

    static int readInt(DataInputStream dis) throws IOException {
        int num = 0;
        int sign = 1;
        int c = dis.read();
        while (c <= ' ') c = dis.read();
        if (c == '-') {
            sign = -1;
            c = dis.read();
        }
        while (c >= '0' && c <= '9') {
            num = num * 10 + c - '0';
            c = dis.read();
        }
        return num * sign;
    }

    static void writeInt(DataOutputStream dos, int val) throws IOException {
        dos.writeBytes(Integer.toString(val));
        dos.writeByte('\n');
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        int b = s.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextInt();
        }
        System.out.println(maxCuttings(arr, b));
    }

    private static int maxCuttings(int[] arr, int b) {
        ArrayList<Integer> costs = new ArrayList<>();
        int numEvens = arr[0] % 2 == 0 ? 1 : 0;
        int numOdds = arr[0] % 2 == 1 ? 1 : 0;
        int numCuttings = 0;
        for (int i = 1; i < arr.length; i++) {
            if (numOdds == numEvens&& Math.abs(arr[i]-arr[i-1])<=b) {
                numEvens = 0;
                numOdds = 0;
                costs.add(Math.abs(arr[i]-arr[i-1]));
            }
            if (arr[i] % 2 == 0) ++numEvens;
            else ++numOdds;
        }
        Collections.sort(costs);
        for(int i=0;i<costs.size();i++){
            if(b<costs.get(i))
                break;
            ++numCuttings;
            b-=costs.get(i);
        }
        return numCuttings;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalItems = scanner.nextInt();
        int maxBudget = scanner.nextInt();
        int[] numbers = new int[totalItems];
        for (int index = 0; index < totalItems; index++) {
            numbers[index] = scanner.nextInt();
        }
        System.out.println(calculateMaxCuts(numbers, maxBudget));
    }

    private static int calculateMaxCuts(int[] array, int budget) {
        ArrayList<Integer> differences = new ArrayList<>();
        int evenCount = array[0] % 2 == 0 ? 1 : 0;
        int oddCount = array[0] % 2 == 1 ? 1 : 0;
        int cutsMade = 0;
        for (int i = 1; i < array.length; i++) {
            if (oddCount == evenCount && Math.abs(array[i] - array[i - 1]) <= budget) {
                evenCount = 0;
                oddCount = 0;
                differences.add(Math.abs(array[i] - array[i - 1]));
            }
            if (array[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        Collections.sort(differences);
        for (int diff : differences) {
            if (budget < diff) {
                break;
            }
            cutsMade++;
            budget -= diff;
        }
        return cutsMade;
    }
}

