/**
 * @author Don Li
 */
public class LittleCLoves3II {
    void solve() {
        long n = in.nextInt(), m = in.nextInt();
        if (n > m) {
            long tmp = n; n = m; m = tmp;
        }

        if (n == 1) {
            out.println(m / 6 * 6 + Math.max(m % 6 - 3, 0) * 2);
            return;
        }

        if (n == 2) {
            if (m == 2) out.println(0);
            else if (m == 3) out.println(4);
            else if (m == 7) out.println(12);
            else out.println(n * m);
            return;
        }

        out.println(n * m / 2 * 2);
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new LittleCLoves3II().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

