    static class Solver {
        IO io;

        public Solver() {
            this.io = new IO();
            try {
                execute();
            } catch (RuntimeException e) {
                if (!e.getMessage().equals("Clean exit")) {
                    throw e;
                }
            } finally {
                io.close();
            }
        }

        void execute() {
            long n = io.nextLong();
            long m = io.nextLong();
            if (m < n) {
                long temp = m;
                m = n;
                n = temp;
            }

            if (n == 1) {
                io.println(bruteForce(m));
                return;
            }
            if (n == 2) {
                if (m < 3) io.println(0);
                else if (m == 3) io.println(4);
                else if (m == 7) io.println(12);
                else io.println(2 * m);
                return;
            }

            io.println(2 * (n * m / 2));
        }

        long bruteForce(long m) {
            long result = 6 * (m / 6);
            if (m % 6 == 5) result += 4;
            else if (m % 6 == 4) result += 2;
            return result;
        }
    }

