        occ[0]++;
        nbr_vertexes[0] = 1;
        for (int i = 1; i <= n; i++) {
            long[] oc = new long[n / 2 + 1];
            int limite = Math.min(n - i, n / 2);
            for (int j = 0; j <= limite; j++) {
                long h = occ[j];
                if (j + 1 <= limite) {
                    oc[j + 1] += h;
                    oc[j + 1] %= big;
                }
                if (j - 1 >= 0) {
                    oc[j - 1] += h;
                    oc[j - 1] %= big;
