                oc[limite] += occ[limite + 1];
                oc[limite] %= big;
            }
            long sum = 0;
            for (int j = 0; j <= limite; j++) {
                sum += oc[j];
                occ[j] = oc[j];
                sum %= big;
            }
            nbr_vertexes[i] = sum;
        }
