    private static int readInt(DataInputStream dis) throws IOException {
        int ret = 0;
        boolean neg = false;
        byte b = dis.readByte();
        while (b <= ' ') {
            b = dis.readByte();
        }
        if (b == '-') {
            neg = true;
            b = dis.readByte();
        }
        do {
            ret = ret * 10 + b - '0';
            b = dis.readByte();
        } while (b >= '0' && b <= '9');
        return neg ? -ret : ret;
    }
}

