public class Main {
    static int mod = 998244353;

    static long fastPower(long base, long exp) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long modularInverse(long x) {
        return fastPower(x, mod - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());
        long r = Long.parseLong(st.nextToken());

        PrintWriter pw = new PrintWriter(System.out);
        if (l == r) {
            pw.println(1);
            pw.flush();
            return;
        }

        long odds = ((r + 1) / 2) - (l / 2);
        long evens = (r / 2) - ((l - 1) / 2);
        long total = n * m;

        long ans;
        if (total % 2 == 1) {
            ans = fastPower(odds + evens, total);
        } else {
            long sum = (fastPower(odds + evens, total) + fastPower(odds - evens, total)) % mod;
            ans = (sum * modularInverse(2)) % mod;
        }
        pw.println(ans);
        pw.flush();
    }
}

