                        if (Math.toDegrees(Math.acos(cosine)) + 1e-9 < 90) {
                            badIndices.add(i);
                        }
                    }
                }
            }
            writer.println(count - badIndices.size());
            for (int i = 1; i <= count; i++) {
                if (!badIndices.contains(i)) writer.println(i);
            }
        }
        writer.close();
    }
}

