public class P851C
{
	static double eps = 1e-9;
	public static void main(String[] args)
	{
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		if (n > 11)
		{
			System.out.println(0);
			return;
		}
		int[][] arr = new int[n][5];
		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < 5; j++)
			{
				arr[i][j] = scan.nextInt();
			}
		}
		ArrayList<Integer> list = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			boolean good = true;
			Loop:
			for (int j = 0; j < n; j++)
			{
				if (j == i)
					continue;
				for (int k = j+1; k < n; k++)
				{
					if (k == i)
						continue;
					Vector v1 = new Vector(arr[i], arr[j]);
					Vector v2 = new Vector(arr[i], arr[k]);
					double angle = Math.acos(v1.prod(v2)/(v1.mag()*v2.mag()));
					if (angle < Math.PI/2-eps)
					{
						good = false;
						break Loop;
					}
				}
			}
			if (good)
				list.add(i+1);
		}
		System.out.println(list.size());
		for (int i : list)
			System.out.println(i);
	}
	static class Vector
	{
		int[] arr = new int[5];
		Vector(int[] a, int[] b)
		{
			for (int i = 0; i < 5; i++)
			{
				arr[i] = b[i]-a[i];
			}
		}
		double mag()
		{
			double sum = 0;
			for (int i = 0; i < arr.length; i++)
			{
				sum += arr[i]*arr[i];
			}
			return Math.sqrt(sum);
		}
		int prod(Vector v)
		{
			int sum = 0;
			for (int i = 0; i < arr.length; i++)
			{
				sum += arr[i]*v.arr[i];
			}
			return sum;
		}
	}
}

