import java.io.*;
import java.util.*;
public class div375B
{
	BufferedReader in;
	PrintWriter ob;
	StringTokenizer st;
	public static void main(String[] args) throws IOException {
		new div375B().run();
	}
	void run() throws IOException {
		in=new BufferedReader(new InputStreamReader(System.in));
		ob=new PrintWriter(System.out);
		solve();
		ob.flush();
	}
	void solve() throws IOException {
		int n=ni();
		char s[]=ns().toCharArray();
		int ans1=0,ans2=0;
		for (int i=0; i<n ; i++ ) {
			if(s[i]=='(') {
				int c=0;
				while(i+1<n) {
					if(s[i+1]==')') {
						if(c>0)++ans2;
						break;
					}
					if(s[i+1]=='_'){
						if(c>0) {
							++ans2;
							c=0;
						}
					}
					else
						++c;
					++i;
				}	
			}
			else if(s[i]==')' || s[i]=='_') {
				int c=0;
				while(i+1<n && s[i+1]!=')' && s[i+1]!='_' && s[i+1]!='(') {++c;++i;}
				ans1=Math.max(c,ans1);
			}
			else {
				int c=0;
				while(i<n && s[i]!=')' && s[i]!='_' && s[i]!='(') {++c;++i;}
				ans1=Math.max(c,ans1);	
				--i;
			}
		}
		ob.println(ans1+" "+ans2);
	}
	String ns()throws IOException {
		return nextToken();
	}
	int ni() throws IOException {
		return Integer.parseInt(nextToken());
	}
	String nextToken() throws IOException {
		if(st==null || !st.hasMoreTokens())
			st=new StringTokenizer(in.readLine());
		return st.nextToken();
	}
}

import java.io.*;
import java.util.*;

public class Div375BVariant1 {
    BufferedReader reader;
    PrintWriter writer;
    StringTokenizer tokenizer;

    public static void main(String[] args) throws IOException {
        new Div375BVariant1().execute();
    }

    void execute() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        process();
        writer.flush();
    }

    void process() throws IOException {
        int length = readInt();
        char[] sequence = readString().toCharArray();
        int maxSegment = 0, nestedCount = 0;
        for (int index = 0; index < length; index++) {
            if (sequence[index] == '(') {
                int tempCount = 0;
                for (int j = index + 1; j < length; j++) {
                    if (sequence[j] == ')') {
                        if (tempCount > 0) nestedCount++;
                        break;
                    }
                    if (sequence[j] == '_') {
                        if (tempCount > 0) {
                            nestedCount++;
                            tempCount = 0;
                        }
                    } else {
                        tempCount++;
                    }
                }
            } else if (sequence[index] == ')' || sequence[index] == '_') {
                int count = 0;
                for (int j = index + 1; j < length && sequence[j] != ')' && sequence[j] != '_' && sequence[j] != '('; j++) {
                    count++;
                }
                maxSegment = Math.max(maxSegment, count);
            } else {
                int count = 0;
                for (int j = index; j < length && sequence[j] != ')' && sequence[j] != '_' && sequence[j] != '('; j++) {
