import java.util.*;

public class GregAndFriends {
    static int aCount, bCount, totalN, maxK;
    static long MOD = 1000000007;
    static long[][] chooseArr = new long[100][100];
    static Map<Integer, Pair> stateMap = new HashMap<>();
    static Queue<Integer> stateQueue = new LinkedList<>();
    static class Pair {
        int depth;
        long ways;
        Pair(int d, long w) {
            this.depth = d;
            this.ways = w;
        }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextInt();
        maxK = sc.nextInt();
        aCount = 0;
        bCount = 0;
        for(int i=0; i<totalN; i++) {
            int val = sc.nextInt();
            if(val == 50) aCount++;
            else bCount++;
        }
        sc.close();
        generateChoose();
        int startState = 1000000 + 100 * aCount + bCount;
        stateQueue.add(startState);
        stateMap.put(startState, new Pair(0, 1));
        while(!stateQueue.isEmpty()) {
            processState(stateQueue.poll());
        }
        if(stateMap.containsKey(0))
            System.out.println(stateMap.get(0).depth + "\n" + stateMap.get(0).ways);
        else
            System.out.println("-1\n0");
    }
    static void processState(int state) {
        int side = state / 1000000;
        int nA = (state % 1000000) / 100;
        int nB = state % 100;
        if(side > 0) {
            for(int i=nA; i>=0 && 50*(nA - i) <= maxK; i--) {
                for(int j=nB; j>=0 && 50*(nA - i) + 100*(nB - j) <= maxK; j--) {
                    if(i != nA || j != nB)
                        updateState(i, j, side, state, chooseArr[nA][i] * chooseArr[nB][j] % MOD);
                }
            }
        } else {
            for(int i=nA; i<=aCount && 50*(i - nA) <= maxK; i++) {
                for(int j=nB; j<=bCount && 50*(i - nA) + 100*(j - nB) <= maxK; j++) {
                    if(i != nA || j != nB)
                        updateState(i, j, side, state, chooseArr[aCount - nA][i - nA] * chooseArr[bCount - nB][j - nB] % MOD);
                }
            }
        }
    }
    static void updateState(int i, int j, int side, int prevState, long edgeWays) {
        int newState = 1000000 * (1 - side) + i * 100 + j;
        int newDepth = stateMap.get(prevState).depth + 1;
        if(!stateMap.containsKey(newState)) {
            stateMap.put(newState, new Pair(newDepth, 0));
            stateQueue.add(newState);
        }
        if(stateMap.get(newState).depth == newDepth)
            stateMap.get(newState).ways = (stateMap.get(newState).ways + stateMap.get(prevState).ways * edgeWays % MOD) % MOD;
    }
    static void generateChoose() {
        for(int i=0; i<100; i++) chooseArr[i][0] = 1;
        for(int i=1; i<100; i++) {
            for(int j=1; j<=i; j++) {
                chooseArr[i][j] = (chooseArr[i-1][j-1] + chooseArr[i-1][j]) % MOD;
            }
        }
    }
}

