    static class CGregAndFriends {
        long mod = 1000000007;
        long INF = (long) 1e18 + 1;
        PrintWriter out;
        InputReader in;
        long[][] nCr = new long[100][100];

        long f(long p, int a, int b, int c, int d) {
            p *= nCr[a][b];
            p %= mod;
            p *= nCr[c][d];
            p %= mod;
            return p;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            int n = ni();
            int maxLoad = ni();
            int countA = 0, countB = 0;
            int i, j, k;
            for (i = 0; i < 100; i++) {
                for (j = 0; j <= i; j++) {
                    nCr[i][j] = (j == 0 || j == i) ? 1 : (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod;
                }
            }
            for (i = 0; i < n; i++) {
                if (ni() == 50)
                    countA++;
                else
                    countB++;
            }
            long[][][] dist = new long[200][200][2];
            long[][][] dp = new long[200][200][2];
            for (i = 0; i < 200; i++) {
                for (j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                }
            }
            dist[0][0][0] = 0;
            dp[0][0][0] = 1;
            Queue<Tuple> q = new LinkedList<>();
            q.add(new Tuple(0, 0, 0, 0));
            while (!q.isEmpty()) {
                Tuple t = q.poll();
                int x = t.x;
                int y = t.y;
                int z = t.z;
                long d = dist[x][y][z];
