            if (index == sequence.length() - 1 && sequence.charAt(index) == lastCharRead && switchFlag) {
                changeCount++;
            }
            if (sequence.charAt(index) != lastCharRead) {
                lastCharRead = sequence.charAt(index);
                changeCount += switchFlag ? 0 : 1;
                switchFlag = false;
            }
        }
        System.out.println(changeCount);
    }
}

