	public static void longestPrefixSuffix(int[] lps, String str, int n){
		lps[0]=0;
		for(int i=1; i<n; i++){
			int l=lps[i-1];
			while(l>0 && str.charAt(i)!=str.charAt(l))
				l=lps[l-1];
			if(str.charAt(i)==str.charAt(l))
				l++;
			lps[i]=l;
		}
	}

