	public static int[][] rotate(int[][] input){
		int n=input.length;
		int m=input[0].length;
		int[][] output=new int[m][n];
		for(int i=0; i<n; i++)
			for(int j=0; j<m; j++)
				output[j][n-1-i]=input[i][j];
		return output;
	}

