	public static long xnor(long num1, long num2){
		if(num1<num2){
			long temp=num1; num1=num2; num2=temp;
		}
		num1=togglebit(num1);
		return num1^num2;
	}

	public static long togglebit(long n){
		if(n==0) return 1;
		long i=n;
		n|=n>>1; n|=n>>2; n|=n>>4; n|=n>>8; n|=n>>16;
		return i^n;
	}

