		boolean[] prime=new boolean[sieve+1];
		Arrays.fill(prime, false);
		for(int i=2; i*i<=sieve; i++){
			if(!prime[i]){
				for(int j=i*i; j<=sieve; j+=i)
					prime[j]=true;
			}
