	public static long countSubarraysSumToK(long[] arr, long sum){
		Map<Long, Long> map=new HashMap<>();
		int n=arr.length;
		long prefixsum=0, count=0;
		for(int i=0; i<n; i++){
			prefixsum+=arr[i];
			if(prefixsum==sum) count++;
			if(map.containsKey(prefixsum-sum))
				count+=map.get(prefixsum-sum);
			map.put(prefixsum, map.getOrDefault(prefixsum, 0L)+1);
		}
		return count;
	}

	public static ArrayList<Integer> kmpAlgorithm(String str, String pat){
		ArrayList<Integer> list=new ArrayList<>();
		int n=str.length(), m=pat.length();
		String q=pat+"#"+str;
		int[] lps=new int[n+m+1];
		longestPrefixSuffix(lps, q, n+m+1);
		for(int i=m+1; i<n+m+1; i++){
			if(lps[i]==m) list.add(i-2*m);
		}
		return list;
	}

	public static void longestPrefixSuffix(int[] lps, String str, int n){
		lps[0]=0;
		for(int i=1; i<n; i++){
			int l=lps[i-1];
			while(l>0 && str.charAt(i)!=str.charAt(l))
				l=lps[l-1];
			if(str.charAt(i)==str.charAt(l))
				l++;
			lps[i]=l;
		}
	}

	public static void eulerTotientFunction(int[] arr, int n){
		for(int i=1; i<=n; i++) arr[i]=i;
		for(int i=2; i<=n; i++){
			if(arr[i]==i){
				arr[i]=i-1;
				for(int j=2*i; j<=n; j+=i)
					arr[j]=(arr[j]*(i-1))/i;
			}
		}
	}

	public static long nCr(int n, int k){
		long ans=1L;
		k=k>n-k ? n-k : k;
		for(int j=1; j<=k; j++, n--){
			if(n%j==0) ans*=n/j;
			else if(ans%j==0) ans=ans/j*n;
			else ans=(ans*n)/j;
		}
		return ans;
	}

