	public static long binarySerachGreater(int[] arr, int start, int end, int val){
		if(start>end) return 0;
		int mid=(start+end)/2;
		if(arr[mid]<=val)
			return binarySerachGreater(arr, mid+1, end, val);
		else
			return binarySerachGreater(arr, start, mid-1, val)+(end-mid+1);
	}

