        ERockPaperScissors game = new ERockPaperScissors();
        game.play(br, pw);
        pw.close();
    }

    static class ERockPaperScissors {
        int minDiff;

        public void evaluate(List<int[]> pairs, int[] a, int[] b) {
            for (int[] p : pairs) {
                int m = Math.min(a[p[0]], b[p[1]]);
                b[p[1]] -= m;
                a[p[0]] -= m;
            }
            int total = 0;
            for (int val : a) total += val;
            minDiff = Math.min(minDiff, total);
        }

        public void generatePermutations(List<int[]> pairs, int start, int[] a, int[] b) {
            evaluate(pairs, a.clone(), b.clone());
            for (int i = start; i < pairs.size(); i++) {
                Collections.swap(pairs, i, start);
                generatePermutations(pairs, start + 1, a, b);
                Collections.swap(pairs, i, start);
