public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int n = Integer.parseInt(reader.readLine());
        String[] parts = reader.readLine().split(" ");
        int a1 = Integer.parseInt(parts[0]);
        int a2 = Integer.parseInt(parts[1]);
        int a3 = Integer.parseInt(parts[2]);
        parts = reader.readLine().split(" ");
        int b1 = Integer.parseInt(parts[0]);
        int b2 = Integer.parseInt(parts[1]);
        int b3 = Integer.parseInt(parts[2]);
        int max = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);

        int[] A = {a1, a2, a3};
        int[] B = {b1, b2, b3};
        int[] A_copy, B_copy;
        int[] results = new int[6];

        for (int i = 0; i < 6; i++) {
            A_copy = A.clone();
            B_copy = B.clone();
            int total = 0;
            if (i == 0) {
                // First variant: process in order 0,1,2
                total = process(A_copy, B_copy, new int[]{0,1,2});
            } else if (i == 1) {
                // Second variant: process in order 2,1,0
                total = process(A_copy, B_copy, new int[]{2,1,0});
            } else if (i == 2) {
                // Third variant: process in order 1,2,0
                total = process(A_copy, B_copy, new int[]{1,2,0});
            } else if (i == 3) {
                // Fourth variant: process in order 0,2,1
                total = process(A_copy, B_copy, new int[]{0,2,1});
            } else if (i == 4) {
                // Fifth variant: process in order 2,0,1
                total = process(A_copy, B_copy, new int[]{2,0,1});
            } else {
                // Sixth variant: process in order 1,0,2
                total = process(A_copy, B_copy, new int[]{1,0,2});
            }
            results[i] = total;
        }

        int minVal = Arrays.stream(results).min().getAsInt();
        writer.print(minVal + " " + max);
        writer.close();
    }

    static int process(int[] A, int[] B, int[] order) {
        int sum = 0;
        for (int idx : order) {
            int bVal = B[idx];
            for (int j = 0; j < 3; j++) {
                int minVal = Math.min(A[j], bVal);
                A[j] -= minVal;
                bVal -= minVal;
            }
            sum += A[0] + A[1] + A[2];
        }
        return sum;
    }
}

