import java.io.*;

public class Test {
  static final PrintWriter pw = new PrintWriter(System.out);
  int R, C;
  long[][] ch = new long[61][61];
  int[] cntA = new int[61], cntB = new int[61];
  long best = Long.MAX_VALUE;
  String str;
  Map<Long, Long> cache = new HashMap<>();

  public static void main(String[] args) {
    new Test().run();
  }

  void run() {
    R = readInt();
    C = readInt();
    generatePascal();
    long x = 0, y = 0;
    int v1 = R + C, v2 = R + C;
    while (v1 >= R && v2 >= R) {
      if (x > y) {
        long c = ch[v1][R] - ch[v1 - 1][R];
        long o = ch[v2][R];
        y += c * o;
        v1--;
      } else {
        long c = ch[v2][R] - ch[v2 - 1][R];
        long o = ch[v1][R];
        x += c * o;
        v2--;
      }
    }
    best = Math.abs(x - y);
    dfs(0, 0, R + C, R + C);
    str = readLine();
    for (int i = 0; i < 2 * (R + C); i++) {
      cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
      cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
    }
    long ans = solve(0, 0, R + C, R + C);
    pw.println(ans);
    pw.flush();
  }

  void generatePascal() {
    for (int i = 0; i <= 2*(R + C); i++)
      for (int j = 0; j <= i; j++)
        if (j == 0 || j == i) ch[i][j] = 1;
        else ch[i][j] = ch[i - 1][j - 1] + ch[i - 1][j];
  }

  int readInt() {
    try {
      String line = new BufferedReader(new InputStreamReader(System.in)).readLine();
      return Integer.parseInt(line.trim());
    } catch (IOException e) {
      return 0;
    }
  }

  String readLine() {
    try {
      return new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
    } catch (IOException e) {
      return "";
    }
  }

  long solve(long x, long y, int v1, int v2) {
    long diff = Math.abs(x - y);
    if (diff - ch[v1][R] * ch[v2][R] > best) return 0;
    long key = x * 10000 + v1 * 100 + v2;
    Long v = cache.get(key);
    if (v != null) return v;
    if (v1 < R || v2 < R) {
      if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
        int sum = v1 + v2;
        v1 -= cntA[sum];
        v2 -= cntB[sum];
        return ch[v1 + v2][v1];
      }
      return 0;
    }
    long ans = 0;
    char c = str.charAt(v1 + v2 - 1);
    if (c != 'B') {
      long cur = ch[v1][R] - ch[v1 - 1][R];
      long other = ch[v2][R];
      ans += solve(x, y + cur * other, v1 - 1, v2);
    }
    if (c != 'A') {
      long cur = ch[v2][R] - ch[v2 - 1][R];
      long other = ch[v1][R];
      ans += solve(x + cur * other, y, v1, v2 - 1);
    }
    cache.put(key, ans);
    return ans;
  }
}

