    private static int readInt(DataInputStream dis) throws Exception {
        int ret = 0;
        int c = dis.read();
        while (c <= ' ') c = dis.read();
        boolean neg = false;
        if (c == '-') {
            neg = true;
            c = dis.read();
        }
        do {
            ret = ret * 10 + c - '0';
            c = dis.read();
        } while (c >= '0' && c <= '9');
        return neg ? -ret : ret;
    }
