        }
        int c = n - (int) k;
        long[] ff = new long[n + n];
        long[] gg = new long[n + n];
        long f = 1;
        for (int i = 0; i < n + n; i++) {
            ff[i] = f;
            gg[i] = modInverse(f, MD);
            f = (f * (i + 1)) % MD;
        }
        long ans = 0;
        for (int a = 1; a <= c; a++) {
            long x = (power(a, n, MD) * ch(c, a, ff, gg, MD)) % MD;
            ans += (a % 2 == 0 ? 1 : -1) * x;
        }
        ans = ((ans % MD) + MD) % MD;
        ans = (ans * ch(n, c, ff, gg, MD)) % MD;
        if (k > 0) {
            ans = (ans * 2) % MD;
        }
        System.out.println(ans);
