class MathUtils {

    public static final double EPS = 1e-12;

    public static final Comparator<Double> EPS_COMPARATOR = (x, y) -> {
        if (x + EPS < y) {
            return -1;
        } else if (x - EPS > y) {
            return 1;
        } else {
            return 0;
        }
    };

    public static int compare(double x, double y) {
        return EPS_COMPARATOR.compare(x, y);
    }

    /**
     * Returns the index of the first element in the range <b>[left, right)</b> which <i>leftShouldAdvance</i> tested to
     * be <i>false</i>.
     */
    public static int binarySearch(int left, int right, IntPredicate leftShouldAdvance) {
        while (left < right) {
            var mid = left + (right - left) / 2;
            if (leftShouldAdvance.test(mid)) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }

    /**
     * Returns the index of the first element in <i>a</i> which >= <i>x</i>.
     */
    public static int lowerBound(int[] a, int x) {
        return binarySearch(0, a.length, mid -> a[mid] < x);
    }

    public static int lowerBound(long[] a, long x) {
        return binarySearch(0, a.length, mid -> a[mid] < x);
    }

    /**
     * Returns the index of the first element in <i>a</i> which > <i>x</i>.
     */
    public static int upperBound(int[] a, int x) {
        return binarySearch(0, a.length, mid -> a[mid] <= x);
    }

    public static int upperBound(long[] a, long x) {
        return binarySearch(0, a.length, mid -> a[mid] <= x);
    }

    /**
     * Searches for the maximum value of a unimodal function f(x).
     * <p>
     * A function f(x) is a <b>unimodal function</b> if for some value m, it is <b>monotonically increasing</b> for x ≤
     * m and <b>monotonically decreasing</b> for x ≥ m. In that case, the maximum value of f(x) is f(m) and there are no
     * other local maxima.
     */
    public static int ternarySearchMaxInt(int left, int right, IntUnaryOperator f) {
        return binarySearch(left, right, mid -> f.applyAsInt(mid) < f.applyAsInt(Math.min(mid + 1, right - 1)));
    }

    public static int ternarySearchMaxLong(int left, int right, IntToLongFunction f) {
        return binarySearch(left, right, mid -> f.applyAsLong(mid) < f.applyAsLong(Math.min(mid + 1, right - 1)));
    }

    public static long gcd(long a, long b) {
        while (b > 0) {
            var t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    /**
     * Solves x and y such that ax + by = gcd(a, b).
     */
    public static long extendedEuclidean(long a, long b, long[] xy) {
        if (b == 0L) {
            xy[0] = 1L;
            xy[1] = 0L;

            return a;
        }

        var r = extendedEuclidean(b, a % b, xy);
        var t = xy[0];
        xy[0] = xy[1];
        xy[1] = t - a / b * xy[1];

        return r;
    }

    public static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

}

// all a, b < mod
class Modulo {

    private final long mod;

    public Modulo(long mod) {
        this.mod = mod;
    }

    public long plus(long a, long b) {
        var c = a + b;
        if (c >= mod) {
            c -= mod;
        }
        return c;
    }

    public long minus(long a, long b) {
        var c = a - b;
        if (c < 0) {
            c += mod;
        }
        return c;
    }

    public long times(long a, long b) {
        return a * b % mod;
    }

    public long div(long a, long b) {
        return times(a, pow(b, mod - 2));
    }

    public long pow(long a, long b) {
        long c = 1;

        while (b > 0) {
            if ((b & 1) > 0) {
                c = c * a % mod;
            }
            a = a * a % mod;
            b >>= 1;
        }

        return c;
    }

    public long combination(int n, int k) {
        return div(factorial(n), times(factorial(k), factorial(n - k)));
    }

    public long combination(int n, int k, long[] factorials) {
        return div(factorials[n], times(factorials[k], factorials[n - k]));
    }

    public long factorial(int n) {
        var f = 1L;
        for (var i = 1; i <= n; i++) {
            f = f * i % mod;
        }
        return f;
    }

    public long[] factorials(int n) {
        var f = new long[n + 1];
        f[0] = 1L;
        for (var i = 1; i <= n; i++) {
            f[i] = f[i - 1] * i % mod;
        }
        return f;
    }

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;

public class E {

    public static void main(String[] args) {
        new E().execute();
    }

    private void execute() {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long kt = scanner.nextLong();

        if (kt >= n) {
            System.out.println(0);
            return;
        }

        int k = (int) kt;
        long mod = 998244353L;
        long[] factorials = new long[n + 1];
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (factorials[i - 1] * i) % mod;
        }

        long ans = 0;
        int c = n - k;
        for (int i = 0; i <= c; i++) {
            long comb = (factorials[c] * modInverse(factorials[i], mod) % mod) * modInverse(factorials[c - i], mod) % mod;
            long power = modPow(c - i, n, mod);
            long t = (comb * power) % mod;
            if (i % 2 == 0) {
                ans = (ans + t) % mod;
            } else {
                ans = (ans - t + mod) % mod;
            }
        }
        long totalComb = (factorials[n] * modInverse(factorials[n - k], mod) % mod) * modInverse(factorials[k], mod) % mod;
        ans = (ans * totalComb) % mod;
        if (k > 0) {
            ans = (ans * 2) % mod;
        }
        System.out.println(ans);
        scanner.close();
    }

    private long modInverse(long a, long m) {
        return modPow(a, m - 2, m);
    }

    private long modPow(long base, int exp, long mod) {
        long result = 1;
        long b = base % mod;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}

