		int n = scanner.nextInt();
		long k = scanner.nextLong();
		final long[] factArray = new long[n + 1], invArray = new long[n + 1];
		final int MOD = 998244353;
		factArray[0] = 1;
		for (int i = 0; i < n; ++i) factArray[i + 1] = factArray[i] * (i + 1) % MOD;
		invArray[n] = IntMath.pow((int) factArray[n], MOD - 2, MOD);
		for (int i = n; i > 0; --i) invArray[i - 1] = invArray[i] * i % MOD;
		BiFunction<Integer, Integer, Long> combination = (i, j) -> factArray[i] * invArray[j] % MOD * invArray[i - j] % MOD;
		if (k == 0) {
			writer.println(factArray[n]);
		} else if (k > n) {
			writer.println(0);
		} else {
			int kVal = (int) k;
			int remaining = n - kVal;
			long totalCount = 0;
			for (int i = 1; i <= remaining; ++i) {
				long temp = combination.apply(remaining, i) * IntMath.pow(i, n, MOD) % MOD;
				totalCount += ((remaining - i) & 1) != 0 ? -temp : temp;
			}
			totalCount = (totalCount % MOD + MOD) % MOD;
			totalCount = totalCount * 2 * combination.apply(n, kVal) % MOD;
			writer.println(totalCount);
		}
	}

	static class FastScanner {
		private final java.io.InputStream inStream = System.in;
		private final byte[] buf = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) return true;
			ptr = 0;
			try {
				buflen = inStream.read(buf);
			} catch (java.io.IOException e) {
				e.printStackTrace();
			}
			return buflen > 0;
		}
		private byte readByte() {
			return hasNextByte() ? buf[ptr++] : -1;
		}
		private static boolean isPrintable(byte c) {
			return c > 32 || c < 0;
		}
		private static boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}
		public boolean hasNext() {
			while (hasNextByte() && !isPrintable(buf[ptr])) ptr++;
			return hasNextByte();
		}
		public String next() {
			if (!hasNext()) throw new java.util.NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			byte b;
			while (isPrintable(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}
		public long nextLong() {
			if (!hasNext()) throw new java.util.NoSuchElementException();
			long num = 0;
			try {
				byte b = readByte();
				if (b == '-') {
					while (isNumber(b = readByte())) num = num * 10 - (b - '0');
					return num;
				} else if (!isNumber(b)) throw new NumberFormatException();
				do num = num * 10 + (b - '0'); while (isNumber(b = readByte()));
			} catch (java.util.NoSuchElementException e) {
			}
			return num;
		}
		public int nextInt() {
			if (!hasNext()) throw new java.util.NoSuchElementException();
			int num = 0;
			try {
				byte b = readByte();
				if (b == '-') {
					while (isNumber(b = readByte())) num = num * 10 - (b - '0');
					return num;
				} else if (!isNumber(b)) throw new NumberFormatException();
				do num = num * 10 + (b - '0'); while (isNumber(b = readByte()));
			} catch (java.util.NoSuchElementException e) {
			}
			return num;
		}
		public double nextDouble() {
			return Double.parseDouble(next());
		}
	}
}

