        for (int i = (int) (n - K), s = 1; i >= 1; i--, s = mod - s) {
            ans += C(n, i, mod, fif) * pow(i, n, mod) % mod * s % mod * C((int) (n - i), (int) K, mod, fif);
            ans %= mod;
        }
        ans = ans * 2 % mod;
        System.out.println(ans);
    }

    public static long pow(long a, long n, long mod) {
        long ret = 1;
        for (int x = 63 - Long.numberOfLeadingZeros(n); x >= 0; x--) {
            ret = ret * ret % mod;
            if ((n << (63 - x)) < 0)
                ret = ret * a % mod;
        }
        return ret;
    }

    public static long C(int n, int r, int mod, int[][] fif) {
        if (n < 0 || r < 0 || r > n)
            return 0;
        return (long) fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
    }

    public static int[][] enumFIF(int n, int mod) {
        int[] f = new int[n + 1];
        int[] invf = new int[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            f[i] = (int) ((long) f[i - 1] * i % mod);
        }
        long a = f[n], b = mod;
        long p = 1, q = 0;
        while (b > 0) {
            long c = a / b;
            long d = a;
            a = b;
            b = d % b;
            d = p;
            p = q;
            q = d - c * q;
        }
        invf[n] = (int) (p < 0 ? p + mod : p);
        for (int i = n - 1; i >= 0; i--) {
            invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
        }
        return new int[][] { f, invf };
    }
}

