        dp[encode(aa, m)] = 0;
        while (n-- > 0) {
            Arrays.fill(dq, -1);
            for (int a = 0; a < p; a++) {
                if (dp[a] < 0) continue;
                decode(aa, m, a, 3);
                for (int b = 0; b < (1 << m); b++) {
