        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        n = sc.nextInt();
        mod = sc.nextInt();
        offset = n * (n - 1);
        dp = new int[2][n][2 * offset + 1];

        for (int[][] x : dp)
            for (int[] y : x)
                Arrays.fill(y, -1);

        pw.println(dp2(0));
        pw.flush();
    }

    static long gcd(long a, long b) {
        if (a == 0)
            return b;
        return gcd(b % a, a);
