        for (int i = n - 1; i >= 0; i--) {
            int c = n - 1 - i;
            temp = dp.clone();
            for (int j = 0; j < dp.length; j++) {
                dp[j] = 0;
            }
            int limit = (c * (c - 1)) / 2;
            int count = 0;
            for (int cur = -c; cur < 0; cur++) {
                int pairs = c + cur + 1;
                for (int j = mid - cur + 1; j <= mid + limit; j++) {
