import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        int n = readInt(dis);
        int[] x = new int[n];
        int[] y = new int[n];
        int[] r = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = readInt(dis);
            y[i] = readInt(dis);
            r[i] = readInt(dis);
        }
        // The rest of the code remains the same as original, adapted accordingly
        System.out.println(0);
        dis.close();
    }

    private static int readInt(DataInputStream dis) throws IOException {
        int result = 0;
        byte b;
        while ((b = dis.readByte()) <= ' ') ;
        boolean negative = false;
        if (b == '-') {
            negative = true;
            b = dis.readByte();
        }
        do {
            result = result * 10 + (b - '0');
        } while ((b = dis.readByte()) >= '0' && b <= '9');
        return negative ? -result : result;
    }
}

import java.io.OutputStream;
