        }

        public double mag2() {
            return dot(this);
        }

        public double mag() {
            return Math.sqrt(mag2());
        }

        public Vec unit() {
            return scale(1 / mag());
        }

        public Vec rot90() {
            return new Vec(-y, x);
        }

        public Vec rot270() {
            return new Vec(y, -x);
        }

        public boolean equals(Object o) {
