        List<Integer>[] pos = new ArrayList[3];
        for (int i = 0; i < 3; i++) pos[i] = new ArrayList<>();
        int idx = 0;
        for (char x : c) {
            System.arraycopy(freq[idx], 0, freq[idx + 1], 0, 3);
            idx++;
            if (x == 'V') {
                freq[idx][0]++;
                cv++;
                pos[0].add(idx);
            } else if (x == 'K') {
                freq[idx][1]++;
                ck++;
                pos[1].add(idx);
            } else {
                freq[idx][2]++;
                cs++;
                pos[2].add(idx);
            }
        }
        int[][][][] dp = new int[cv + 1][ck + 1][cs + 1][3];
        for (int[][][] x : dp) for (int[][] y : x) for (int[] z : y) z[0] = -1;

        System.out.println(dfs(cv, ck, cs, 2, pos, freq, dp));
    }

    static int dfs(int tv, int tk, int ts, int last, List<Integer>[] pos, int[][] freq, int[][][][] dp) {
        int cv = freq.length - 1;
        int ck = freq[0].length - 1;
        int cs = freq[0].length - 1;
        if (tv == cv && tk == ck && ts == cs) return 0;
        if (dp[tv][tk][ts][last] != -1) return dp[tv][tk][ts][last];
        int result = Integer.MAX_VALUE / 2;
        if (tv < cv) {
            int p = pos[0].get(tv);
            int move = Math.max(freq[p][0] - tv, 0) + Math.max(freq[p][1] - tk, 0) + Math.max(freq[p][2] - ts, 0) - 1;
            result = Math.min(result, dfs(tv + 1, tk, ts, 0, pos, freq, dp) + move);
        }
        if (tk < ck && last != 0) {
            int p = pos[1].get(tk);
            int move = Math.max(freq[p][0] - tv, 0) + Math.max(freq[p][1] - tk, 0) + Math.max(freq[p][2] - ts, 0) - 1;
            result = Math.min(result, dfs(tv, tk + 1, ts, 1, pos, freq, dp) + move);
        }
        if (ts < cs) {
            int p = pos[2].get(ts);
            int move = Math.max(freq[p][0] - tv, 0) + Math.max(freq[p][1] - tk, 0) + Math.max(freq[p][2] - ts, 0) - 1;
            result = Math.min(result, dfs(tv, tk, ts + 1, 2, pos, freq, dp) + move);
        }
        return dp[tv][tk][ts][last] = result;
    }
}

