				Arrays.fill(dp[1][i][j], 99999999);
				Arrays.fill(dp[2][i][j], 99999999);
			}
		}
		int nv = 0, nk = 0, ne = 0;
		for(char c : s){
			if(c == 'V'){
				nv++;
			}else if(c ==  'K'){
