        System.err.println("Time = " + (timeEnd - timeBegin));
    }

    @Override
    public void run() {
        try {
            timeBegin = System.currentTimeMillis();
            init();
            solve();
            out.close();
            time();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    int[][][][] dp;
    char[] s;
    int INF = 10000000;

    int count(char[] s, char target, int v, int k, int x) {
        int answer = 0;
        for (char c : s) {
            if (c == 'V') {
                v--;
                if (v == 0 && target == 'V') return answer;
                if (v < 0) answer++;
            }
            if (c == 'K') {
                k--;
                if (k == 0 && target == 'K') return answer;
                if (k < 0) answer++;
            }
            if (c == 'X') {
                x--;
                if (x == 0 && target == 'X') return answer;
                if (x < 0) answer++;
            }
        }
        throw new RuntimeException();
    }

    private void solve() throws IOException {
        int n = readInt();
        s = readString().toCharArray();
        int vcnt = 0, kcnt = 0, xcnt = 0;
        for (int i = 0; i < s.length; i++) {
            if (s[i] == 'V') {
                vcnt++;
                continue;
            }
            if (s[i] == 'K') {
                kcnt++;
                continue;
            }
            xcnt++;
            s[i] = 'X';
        }
        dp = new int[vcnt + 1][kcnt + 1][xcnt + 1][3];
        for (int[][][] x : dp) {
            for (int[][] xx : x) {
                for (int[] xxx : xx) {
                    Arrays.fill(xxx, INF);
                }
            }
        }
        dp[0][0][0][0] = dp[0][0][0][1] = dp[0][0][0][2] = 0;
        //V,K,X
        for (int v = 0; v <= vcnt; v++) {
            for (int k = 0; k <= kcnt; k++) {
                for (int x = 0; x <= xcnt; x++) {
                    int rv = v + 1 <= vcnt ? count(s, 'V', v + 1, k, x) : 0;
                    int rk = k + 1 <= kcnt ? count(s, 'K', v, k + 1, x) : 0;
                    int rx = x + 1 <= xcnt ? count(s, 'X', v, k, x + 1) : 0;

                    for (int now = 0; now < 3; now++) {
                        if (v + 1 <= vcnt) dp[v + 1][k][x][0] = Math.min(dp[v + 1][k][x][0], dp[v][k][x][now] + rv);
                        if (now != 0 && k + 1 <= kcnt) dp[v][k + 1][x][1] = Math.min(dp[v][k + 1][x][1], dp[v][k][x][now] + rk);
                        if (x + 1 <= xcnt) dp[v][k][x + 1][2] = Math.min(dp[v][k][x + 1][2], dp[v][k][x][now] + rx);
                    }
                }
            }
        }
        int res = INF;
        for (int i = 0; i < 3; i++) {
            res = Math.min(res, dp[vcnt][kcnt][xcnt][i]);
        }
        out.println(res);


    }

}

