        if (inp.length == 1) {
            if (inp[0] == '0' || inp[0] == 'X' || inp[0] == '_') count++;
        } else {
            for (String cstr : pos) {
                int X = -1;
                int idx = 0;
                boolean possible = true;
                for (int i = n - 2; i < n; i++) {
                    char curr = inp[i];
                    char strcurr = cstr.charAt(idx++);
                    if (curr == '_') continue;
                    else if (curr == 'X') {
                        if (X == -1) X = (strcurr - '0');
                        else if (X != (strcurr - '0')) {
                            possible = false;
                            break;
                        }
                    } else {
                        if (curr != strcurr) {
                            possible = false;
                            break;
                        }
                    }
                }
                if (!possible) continue;
                if (str.length() == 2) {
                    if (cstr.charAt(0) == '0') continue;
                    count++;
                    continue;
                }
                char[] ninp = Arrays.copyOf(inp, str.length());
                int cntX = 0;
