                    int counter = 1;
                    for (int k = 0; k < str.length() - 2; k++) {
                        if (ninp[k] == '_') {
                            counter *= (k == 0) ? 9 : 10;
                        }
                    }
                    count += counter;
                } else {
                    if (ninp[0] == '0') continue;
