public class Codeforces {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output = new StringBuilder();

        char[] s = reader.readLine().toCharArray();
        boolean hasX = false;
        int length = s.length, index;
        for (index = 0; index < length; index++) {
            hasX |= s[index] == 'X';
        }

        int totalWays = 0;
        char[] s2 = new char[length];
        for (int digit = 0; digit < 10; digit++) {
            int j;
            for (j = 0; j < length; j++) {
                if (s[j] == 'X') s2[j] = (char) ('0' + digit);
                else s2[j] = s[j];
            }
            if (s2[0] == '0') continue;

            int[][] dp = new int[2][25];
            int current = 1;
            dp[0][0] = 1;
            for (j = 0; j < length; j++) {
                for (int k = 0; k < 25; k++) {
                    dp[current][k] = 0;
                }
                int low = 0, high = 9, nextVal;
                if (s2[j] != '_') {
                    low = high = s2[j] - '0';
                } else if (j == 0) {
                    low++;
                }

                for (int k = 0; k < 25; k++) {
                    for (int l = low; l <= high; l++) {
                        nextVal = (k * 10 + l) % 25;
                        dp[current][nextVal] += dp[current ^ 1][k];
                    }
                }
                current ^= 1;
            }
            totalWays += dp[current ^ 1][0];
            if (!hasX) break;
        }

        if (length == 1 && (s[0] == '_' || s[0] == 'X' || s[0] == '0')) totalWays++;
        System.out.println(totalWays);
    }
}

