        }

        int totalCount = 0;
        char[] temp = new char[n];
        for (int digit = 0; digit < 10; digit++) {
            for (i = 0; i < n; i++) {
                if (s[i] == 'X') temp[i] = (char) ('0' + digit);
                else temp[i] = s[i];
            }
            if (temp[0] == '0') continue;

            int[][] dpTable = new int[2][25];
            int currentIdx = 1;
            dpTable[0][0] = 1;
            for (i = 0; i < n; i++) {
