public class Main {
    static Scanner sc = new Scanner(System.in);
    static long[][][] dp;
    static int mod = 998244353;

    public static void main(String[] args) {
        int t = 1;
        while (t-- > 0) {
            String inputStr = sc.nextLine();
            char[] A = inputStr.toCharArray();
            if (A.length == 1 && A[0] == '0') {
                System.out.println("1");
                return;
            }
            if (A[0] == '0') {
                System.out.println("0");
                return;
            }
            if (A.length == 1 && (A[0] == 'X' || A[0] == '_')) {
                System.out.println("1");
                return;
            }
            dp = new long[A.length + 1][25][11];
            for (long[][] layer : dp) {
                for (long[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }
            System.out.println(go(A, 0, 0, 10));
        }
        sc.close();
    }

    static long go(char[] A, int i, int pv, int v) {
        if (i == A.length) {
            return pv == 0 ? 1 : 0;
        }
        if (dp[i][pv][v] != -1) {
            return dp[i][pv][v];
        }
        long ans = 0;
        if (A[i] == '_') {
            for (int j = 0; j < 10; j++) {
                if (i == 0 && j == 0) continue;
                int y = (pv * 10 + j) % 25;
                ans += go(A, i + 1, y, v);
            }
        } else if (A[i] == 'X') {
            if (v != 10) {
                ans += go(A, i + 1, (pv * 10 + v) % 25, v);
            } else {
                for (int j = 0; j < 10; j++) {
                    if (i == 0 && j == 0) continue;
                    int y = (pv * 10 + j) % 25;
                    ans += go(A, i + 1, y, j);
                }
            }
        } else {
            int digit = A[i] - '0';
            ans += go(A, i + 1, (pv * 10 + digit) % 25, v);
        }
        return dp[i][pv][v] = ans;
    }
}

