        import java.io.IOException;
        import java.io.InputStreamReader;
        import java.util.StringTokenizer;

public class bubblestrike {
    public static void main(String[] args) throws IOException {
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(f.readLine());
        int x = Integer.parseInt(st.nextToken());
        double prob = Double.parseDouble(st.nextToken());
        int pos = x;
        for (int a=x; a>0; a/=2){
            while (pos-a>=0&&check(pos-a,x-(pos-a),prob)){
                pos-=a;
            }
        }
        System.out.println(pos);

    }
    public static boolean check (int good, int bad, double proba){
        double g=good+0.0;
        double b=bad+0.0;
        double ans = (0.25*b*Math.max(0,b-1.0)*g+(g*(Math.max(0,g-1)*Math.max(0,g-2)/6.0)+b*0.5*(g)*Math.max(0,g-1)))/((g+b)*Math.max(0,g+b-1)*Math.max(0,g+b-2)/6.0);
        return ans >=proba;
    }
}

import java.util.Scanner;

public class bubblestrike {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        double prob = scanner.nextDouble();
        int pos = x;
        for (int a = x; a > 0; a /= 2) {
            while (pos - a >= 0 && check(pos - a, x - (pos - a), prob)) {
                pos -= a;
            }
        }
        System.out.println(pos);
        scanner.close();
    }

    public static boolean check(int good, int bad, double proba) {
        double g = good;
        double b = bad;
        double numerator = (0.25 * b * Math.max(0, b - 1) * g
                + (g * (Math.max(0, g - 1) * Math.max(0, g - 2) / 6.0) + b * 0.5 * g * Math.max(0, g - 1)));
        double denominator = (g + b) * Math.max(0, g + b - 1) * Math.max(0, g + b - 2) / 6.0;
        double ans = numerator / denominator;
        return ans >= proba;
    }
}

