        int n = readInt();
        double p = readDouble();

        int left = 0;
        int right = n - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            double val = computeProbability(mid, n);
            if (val >= p) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        out.println(left);
    }

    private static double computeProbability(int m, int n) {
        long total = choose(n, 3);
        double result = 0.0;
        result += (double) choose(m, 3);
        result += (double) (choose(m, 2) * choose(n - m, 1));
        result += 0.5 * (choose(m, 1) * choose(n - m, 2));
        return result / total;
    }

    private static long choose(int n, int c) {
        if (c > n) return 0;
        if (c == n) return 1;
        long res = 1;
        for (int i = 0; i < c; i++) {
            res *= (n - i);
        }
        for (int i = 1; i <= c; i++) {
            res /= i;
        }
        return res;
    }

