        for (int k = 0; k < (1 << (h - 1)); k++) {
            wws[k] = w;
            w = modh(w * dw, M, H, P);
        }
        long invN = invl(n, P);
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < (1 << i); j++) {
                for (int k = 0, s = j << (h - i), t = s | (1 << (h - i - 1)); k < (1 << (h - i - 1)); k++, s++, t++) {
                    long u = (res[s] - res[t] + 2 * P) * wws[k] % P;
                    res[s] += res[t];
                    if (res[s] >= 2 * P) res[s] -= 2 * P;
                    long Q = (u << 32) * invN >>> 32;
                    res[t] = (u >>> 32) - (Q * P >>> 32) + P;
                }
            }
            if (i < h - 1) {
                for (int k = 0; k < (1 << (h - i - 2)); k++) {
                    wws[k] = wws[k * 2];
                }
            }
        }
        for (int i = 0; i < n; i++) {
            if (res[i] >= P) res[i] -= P;
        }
        for (int i = 0; i < n; i++) {
            int rev = Integer.reverse(i) >>> (32 - h);
            if (i < rev) {
                long tmp = res[i];
                res[i] = res[rev];
                res[rev] = tmp;
            }
        }
        if (inv) {
            for (int i = 0; i < n; i++) {
                res[i] = modh(res[i] * invN, M, H, P);
            }
        }
        return res;
    }

    static long pow(long a, long n, long m) {
        long r = 1;
        for (int x = 63 - Long.numberOfLeadingZeros(n); x >= 0; x--) {
            r = r * r % m;
            if ((n << (63 - x)) < 0) r = r * a % m;
        }
