    }

    static long invl(long a, long m) {
        long b = m, p = 1, q = 0;
        while (b > 0) {
            long c = a / b;
            long d = a;
            a = b;
            b = d % b;
            d = p;
            p = q;
            q = d - c * q;
        }
        return p < 0 ? p + m : p;
    }
