    }

    static void bitReverse(long[] array, int length) {
        for (int i = 1, j = 0; i < length; i++) {
            int bit = length >> 1;
            while (j >= bit) {
                j -= bit;
                bit >>= 1;
            }
            j += bit;
            if (i < j) {
                long temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
