public class Main {
    static final int MOD = 998244353;
    static final int G = 3;

    static long power(long base, int exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static void bitReverse(long[] array, int length) {
        for (int i = 1, j = 0; i < length; i++) {
            int bit = length >> 1;
            for (; j >= bit; bit >>= 1) j -= bit;
            j += bit;
            if (i < j) {
                long temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }

    static void transform(long[] array, int length, int direction) {
        bitReverse(array, length);
        for (int size = 2; size <= length; size <<= 1) {
            long root = power(G, (MOD - 1) / size);
            if (direction == -1) root = power(root, MOD - 2);
            for (int start = 0; start < length; start += size) {
                long w = 1;
                for (int k = start; k < start + size / 2; k++) {
                    long u = array[k];
                    long v = array[k + size / 2] * w % MOD;
                    array[k] = (u + v) % MOD;
                    array[k + size / 2] = (u - v + MOD) % MOD;
                    w = w * root % MOD;
                }
            }
        }
        if (direction == -1) {
            long invLen = power(length, MOD - 2);
            for (int i = 0; i < length; i++) array[i] = array[i] * invLen % MOD;
        }
    }

