        long[] B = new long[size];

        A[0] = 1;
        for (int i = 0; i < m; i++) {
            int x = scanner.nextInt();
            B[x] = 1;
        }

        fft(A, size, 1);
        fft(B, size, 1);

        for (int i = 0; i < size; i++) {
            if (A[i] != 0 && B[i] != 0) {
                A[i] = A[i] * fastPow(B[i], halfN) % MOD;
            } else {
                A[i] = 0;
            }
        }

        fft(A, size, -1);

        long total = 0;
        for (int i = 0; i < size; i++) {
            total = (total + A[i] * A[i]) % MOD;
        }
