public class LuckyTickets {

    private static final int MOD = 998244353;
    private static final int twoPow = 23;
    private static final int ROOT = 15311432;

    private static int reverseBits(int n, int k) {
        int result = 0;
        for (int i = 0; i < k; i++) {
            result = (result << 1) | (n & 1);
            n >>= 1;
        }
        return result;
    }

    private static long fastExponentiation(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static long modularInverse(long a) {
        return fastExponentiation(a, MOD - 2);
    }

    private static long[] computeRootsOfUnity(int k, boolean inverse) {
        long root = fastExponentiation(ROOT, fastExponentiation(2, twoPow - k));
        if (inverse) {
            root = modularInverse(root);
        }
        long[] roots = new long[k];
        if (k > 0) {
            roots[k - 1] = root;
        }
        for (int i = k - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        return roots;
    }

