        long[] result = new long[array.length];
        for (int i = 0; i < array.length; i++) {
            result[reverseBits(i, k)] = array[i];
        }
        return result;
    }

    private static long[] performNTT(long[] coef, int k, boolean inverse) {
        coef = bitReverseOrder(coef, k);
        long[] roots = computeRootsOfUnity(k, inverse);
        for (int s = 0; s < k; s++) {
            int segmentSize = 1 << s;
            for (int start = 0; start < coef.length; start += 2 * segmentSize) {
                long currentRoot = 1;
                for (int j = start; j < start + segmentSize; j++) {
                    long t = (currentRoot * coef[j + segmentSize]) % MOD;
                    long u = coef[j];
                    coef[j] = (u + t) % MOD;
                    coef[j + segmentSize] = (u - t + MOD) % MOD;
                    currentRoot = (roots[s] * currentRoot) % MOD;
                }
            }
        }
        return coef;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        int maxVal = 0;
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
            maxVal = Math.max(maxVal, nums[i]);
        }
        int minSize = n * maxVal + 1;
        int size = 1;
        int k = 0;
        while (size < minSize) {
            size <<= 1;
            k++;
        }
        long[] a = new long[size];
        for (int i = 0; i < nums.length; i++) {
            a[nums[i]] = 1;
        }
        a = performNTT(a, k, false);
        for (int i = 0; i < size; i++) {
            a[i] = fastExponentiation(a[i], n);
        }
        a = performNTT(a, k, true);
        long totalSum = 0;
        for (int i = 0; i < size; i++) {
            totalSum = (totalSum + a[i] * a[i]) % MOD;
        }
        long invSize = modularInverse(size);
        System.out.println((((totalSum * invSize) % MOD) * invSize) % MOD);
    }
}

