public class CF939_D2_F {
    public static void main(String[] args) throws Throwable {
        DataInputStream dis = new DataInputStream(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = readInt(dis) * 2;
        int k = readInt(dis);
        int[] l = new int[k + 1];
        int[] r = new int[k + 1];

        for (int i = 0; i < k; i++) {
            l[i] = readInt(dis);
            r[i] = readInt(dis);
        }
        l[k] = n;

        SparseTable[][] seg = new SparseTable[2][2];
        for (int j = 0; j < 2; j++) {
            int[] a = new int[n / 2 + 2];
            Arrays.fill(a, inf);
            a[n / 2] = 0;
            seg[1][j] = new SparseTable(a);
        }

        int p = 0;
        for (int i = k - 1; i >= 0; i--) {
            for (int j = 0; j < 2; j++) {
                int[] a = new int[n / 2 + 2];
                Arrays.fill(a, inf);
                for (int c = 0; c <= l[i] && c < a.length; c++) {
                    int best = seg[1 - p][j].query(c + l[i + 1] - l[i], c + l[i + 1] - l[i]);
                    best = Math.min(best, 1 + seg[1 - p][1 - j].query(l[i + 1] - (c + r[i] - l[i]), l[i + 1] - c));
                    if (r[i] > l[i]) {
