    static int inf = (int) 1e7;

    static int readInt(DataInputStream dis) throws IOException {
        int ret = 0;
        int c;
        while ((c = dis.read()) != -1 && !isDigit(c))
            ;
        do {
            ret = ret * 10 + (c - '0');
        } while ((c = dis.read()) != -1 && isDigit(c));
        return ret;
    }

    static boolean isDigit(int c) {
        return c >= '0' && c <= '9';
