        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        List<int[]> intervals = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            st = new StringTokenizer(br.readLine());
            intervals.add(new int[]{Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken())});
        }
        intervals.add(new int[]{2 * N, 2 * N});
        int current = 0;
        SegmentTree[] dp = {new SegmentTree(N + 1), new SegmentTree(N + 1)};
        dp[0].assign(0, 0);
        for (int[] interval : intervals) {
            for (int j = N; j >= 0; j--) {
                dp[0].assign(j, dp[0].getVal(j - (interval[0] - current)));
            }
            current = interval[1];
            int size = interval[1] - interval[0];
            for (int j = N; j >= 0; j--) {
                int[] minVals = new int[2];
                for (int z = 0; z <= 1; z++) {
                    int twoSwaps = dp[z].query(j - size, j);
                    int oneSwap = dp[(z + 1) % 2].query(j - size, j);
                    int noSwap;
                    if (z == 1) {
                        noSwap = dp[z].getVal(j);
                    } else {
                        noSwap = dp[z].getVal(j - size);
                    }
                    minVals[z] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                }
                dp[0].assign(j, minVals[0]);
                dp[1].assign(j, minVals[1]);
            }
        }
        int answer = Math.min(dp[0].query(N, N), dp[1].query(N, N));
        if (answer >= Integer.MAX_VALUE) {
            pw.println("Hungry");
        } else {
            pw.println("Full");
            pw.println(answer);
        }
        pw.close();
    }

    static class SegmentTree {
        int[] tree;
        int[] arr;
        int size;

        public SegmentTree(int N) {
            size = N;
            tree = new int[4 * N];
            arr = new int[N];
            Arrays.fill(arr, Integer.MAX_VALUE);
            Arrays.fill(tree, Integer.MAX_VALUE);
        }

        public int query(int l, int r) {
            if (r < 0) return Integer.MAX_VALUE;
            return queryUtil(1, 0, size - 1, Math.max(0, l), r);
        }

        private int queryUtil(int node, int start, int end, int l, int r) {
            if (l > r) return Integer.MAX_VALUE;
            if (l == start && r == end) return tree[node];
            int mid = (start + end) / 2;
            return Math.min(queryUtil(node * 2, start, mid, l, Math.min(r, mid)),
                            queryUtil(node * 2 + 1, mid + 1, end, Math.max(l, mid + 1), r));
        }

        public void assign(int index, int value) {
            arr[index] = value;
            int node = 1, start = 0, end = size - 1;
            int left = 0, right = size - 1;
            while (start != end) {
                int mid = (start + end) / 2;
                if (index <= mid) {
                    node = node * 2;
                    end = mid;
                } else {
                    node = node * 2 + 1;
                    start = mid + 1;
                }
            }
            tree[node] = value;
            node /= 2;
            while (node > 0) {
                tree[node] = Math.min(tree[node * 2], tree[node * 2 + 1]);
                node /= 2;
            }
        }

        public int getVal(int i) {
            if (i < 0 || i >= arr.length) return Integer.MAX_VALUE;
            return arr[i];
        }
    }
}

