import java.io.InputStreamReader;

public class Main {
  public static void main(String[] args) throws IOException {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    long n = Long.parseLong(br.readLine());
    long answer = compute(n);
    System.out.println(answer);
  }

  public static long compute(long n) {
    if (n <= 6) {
      return n;
    }
    long digitsCount = countDigits(n);
    long baseNumber = getOnes(digitsCount);
    long nextBase = getOnes(digitsCount + 1);
    if (n == baseNumber) {
      return digitsCount;
    }
    long minRes = Long.MAX_VALUE;
    long lowerBound = getOnes(digitsCount - 1);
    long lower = n < baseNumber ? lowerBound : baseNumber;
    long upper = n > baseNumber ? nextBase : baseNumber;
    long resLower = compute(n % lower) + (n / lower) * countDigits(lower);
    if (upper - n < n) {
      long resUpper = compute(upper - n) + countDigits(upper);
      minRes = Math.min(resLower, resUpper);
    } else {
      minRes = resLower;
    }
    return minRes;
  }

  public static long countDigits(long n) {
    return (long) Math.floor(Math.log10(n)) + 1;
  }

  public static long getOnes(long count) {
    long res = 0;
    for (int i = 0; i < count; i++) {
      res = res * 10 + 1;
    }
    return res;
  }
}

