    for (int i = 0; i < count; i++) {
      res = res * 10 + 1;
    }
    return res;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
  public static void main(String[] args) throws IOException {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    long n = Long.parseLong(br.readLine());
    long answer = compute(n);
    System.out.println(answer);
  }

  public static long compute(long n) {
    if (n <= 6) {
      return n;
    }
    long digitsCount = getDigits(n);
    long baseNumber = getOnes(digitsCount);
    long nextBaseNumber = getOnes(digitsCount + 1);
    if (n == baseNumber) {
      return digitsCount;
    }
    long resLower = compute(n % baseNumber) + (n / baseNumber) * digitsCount;
    long resUpper = Long.MAX_VALUE;
    if (nextBaseNumber - n < n) {
      resUpper = compute(nextBaseNumber - n) + getDigits(nextBaseNumber);
    }
    return Math.min(resLower, resUpper);
  }

  public static long getDigits(long n) {
    return (long) Math.floor(Math.log10(n)) + 1;
  }

  public static long getOnes(long count) {
    long res = 0;
    for (int i = 0; i < count; i++) {
      res = res * 10 + 1;
    }
    return res;
  }
}

