public class OBADef
{
    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        long num = scan.nextLong();
        System.out.println(""+prog(num,(int)(Math.log10(Math.abs(num)))+1));
    }
    public static long genUnos(long n){
        return (long)(Math.pow(10,n)-1)/9;
    }
    public static long prog(long n, int tam){
        long unos=genUnos(1+tam);
        long veces=n/unos*(1+tam);
        n%=unos;
        if(n==0) return veces;
        return veces+Math.min((1+tam)+prog(unos-n,tam-1),prog(n,tam-1));
        }
}

import java.util.Scanner;

public class OBADef {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long number = scanner.nextLong();
        int length = (int) (Math.log10(Math.abs(number)) + 1);
        System.out.println("" + compute(number, length));
    }

    public static long generateOnes(long n) {
        return (long) (Math.pow(10, n) - 1) / 9;
    }

    public static long compute(long n, int length) {
        long ones = generateOnes(length);
        long total = (n / ones) * (length);
        n %= ones;
        if (n == 0) return total;
        long option1 = (length + 1) + compute(ones - n, length - 1);
        long option2 = compute(n, length - 1);
        return total + Math.min(option1, option2);
    }
}

