        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = 10 * ones[i - 1] + 1;
        }
        long answer = recursiveSolve(ones, n, 16);
        System.out.println(answer);
    }

    private static long recursiveSolve(long[] ones, long n, int index) {
        long q = n / ones[index];
        n %= ones[index];
        long used = q * index;
        if (n == 0) {
            return used;
        } else {
            long option1 = recursiveSolve(ones, n, index - 1);
            long option2 = index + recursiveSolve(ones, ones[index] - n, index - 1);
            return used + Math.min(option1, option2);
        }
    }
}

