    static class TaskE {
        class MinCostMaxFlow {
            ArrayList<Edge>[] adj;
            Edge[][] edgesArray;
            int[] dist;
            int N, S, T, maxFlow, minCost;
            final int INF = Integer.MAX_VALUE / 100;
            int edgeCount = 0;

            class Edge {
                int u, flow, rev, cost;
                Edge(int u, int flow, int cost, int rev) {
                    this.u = u; this.flow = flow; this.cost = cost; this.rev = rev;
                }
            }

            void addEdge(int u, int v, int flow, int cost) {
                int lu = adj[u].size(), lv = adj[v].size();
                adj[u].add(new Edge(v, flow, cost, lv));
                adj[v].add(new Edge(u, 0, -cost, lu));
            }

            void convertToArray() {
                edgesArray = new Edge[N][];
                for (int i = 0; i < N; i++) {
                    int sz = adj[i].size();
                    edgesArray[i] = new Edge[sz];
                    for (int j = 0; j < sz; j++) {
                        edgesArray[i][j] = adj[i].get(j);
                    }
                    adj[i].clear();
                }
            }

            MinCostMaxFlow(int n, int s, int t) {
                N = n; S = s; T = t; maxFlow = 0; minCost = 0;
                adj = new ArrayList[N];
                for (int i = 0; i < N; i++) {
                    adj[i] = new ArrayList<>();
                }
                dist = new int[N];
            }

            boolean bellmanFord(boolean check) {
                Arrays.fill(dist, INF);
                dist[S] = 0;
                for (int i = 0; i < N - 1; i++) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : edgesArray[j]) {
                            if (e.flow == 0) continue;
                            if (dist[j] + e.cost < dist[e.u]) {
                                dist[e.u] = dist[j] + e.cost;
                            }
                        }
                    }
                }
                if (check) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : edgesArray[j]) {
                            if (e.flow == 0) continue;
                            if (dist[j] + e.cost < dist[e.u]) return false;
                        }
                    }
                }
                return true;
            }

            int[] parent, parentEdge;
            int[] node;
            int[] visit;
            int[] prev, prevEdge;
            int[] distance;

            boolean spfa() {
                node = new int[N];
                visit = new int[N];
                parent = new int[N];
                parentEdge = new int[N];
                distance = new int[N];
                Arrays.fill(distance, INF);
                Queue<Integer> q = new LinkedList<>();
                distance[S] = 0;
                q.offer(S);
                while (!q.isEmpty()) {
                    int u = q.poll();
                    visit[u] = 2;
                    for (int i = 0; i < edgesArray[u].length; i++) {
                        Edge e = edgesArray[u][i];
                        if (e.flow > 0 && distance[u] + e.cost < distance[e.u]) {
                            distance[e.u] = distance[u] + e.cost;
                            parent[e.u] = u;
                            parentEdge[e.u] = i;
                            if (visit[e.u] == 0) {
                                q.offer(e.u);
                                visit[e.u] = 1;
                            }
                        }
                    }
                }
                return visit[T] != 0;
            }

            boolean dijkstra() {
                Arrays.fill(distance, INF);
                parent = new int[N];
                parentEdge = new int[N];
                Arrays.fill(parent, -1);
                PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Integer.compare(a.dist, b.dist));
                distance[S] = 0;
                pq.offer(new Pair(S, 0));
                while (!pq.isEmpty()) {
                    Pair p = pq.poll();
                    if (p.dist > distance[p.u]) continue;
                    for (int i = 0; i < edgesArray[p.u].length; i++) {
                        Edge e = edgesArray[p.u][i];
                        if (e.flow > 0 && distance[p.u] + e.cost < distance[e.u]) {
                            distance[e.u] = distance[p.u] + e.cost;
                            parent[e.u] = p.u;
                            parentEdge[e.u] = i;
                            pq.offer(new Pair(e.u, distance[e.u]));
                        }
                    }
                }
                return parent[T] != -1;
            }

            int augment() {
                int flow = Integer.MAX_VALUE;
                for (int p = T; p != S; p = parent[p]) {
                    int u = parent[p], i = parentEdge[p];
                    flow = Math.min(flow, edgesArray[u][i].flow);
                }
                for (int p = T; p != S; p = parent[p]) {
                    int u = parent[p], i = parentEdge[p];
                    edgesArray[u][i].flow -= flow;
                    int rev = edgesArray[u][i].rev;
                    edgesArray[p][rev].flow += flow;
                }
                maxFlow += flow;
                return flow;
            }

            boolean minCostFlow() {
                while (bellmanFord(false)) {
                    minCost += dist[T] * augment();
                }
                return true;
            }

            class Pair {
                int u, dist;
                Pair(int u, int dist) {
                    this.u = u; this.dist = dist;
                }
            }
        }

