                if (pos[i] > 0)
                    mf.addEdge(0, i + 1, pos[i], 0);
            }
            for (int i = 0; i < T; i++) {
                for (int j = 0; j < n; j++) {
                    mf.addEdge(1 + i * n + j, 1 + (i + 1) * n + j, k, 0);
                }
            }
            for (int i = 0; i <= T; i++) {
                for (int j = 1; j <= k; j++) {
                    mf.addEdge(1 + i * n, (T + 1) * n + 1, 1, c * i);
                }
            }
            for (int i = 0; i < m; i++) {
                int a = sc.nextInt() - 1;
                int b = sc.nextInt() - 1;
                for (int j = 0; j < T; j++) {
                    int cost = 0;
                    for (int l = 1; l <= k; l++) {
