                int u, flow, rev, cost;
                Edge(int u, int flow, int cost, int rev) {
                    this.u = u; this.flow = flow; this.cost = cost; this.rev = rev;
                }
            }

            void addEdge(int u, int v, int flow, int cost) {
                int lu = adj[u].size(), lv = adj[v].size();
                adj[u].add(new Edge(v, flow, cost, lv));
                adj[v].add(new Edge(u, 0, -cost, lu));
            }

            void convertToArray() {
                edgesArray = new Edge[N][];
                for (int i = 0; i < N; i++) {
                    int sz = adj[i].size();
                    edgesArray[i] = new Edge[sz];
                    for (int j = 0; j < sz; j++) {
                        edgesArray[i][j] = adj[i].get(j);
                    }
                    adj[i].clear();
                }
            }

            MinCostMaxFlow(int n, int source, int sink) {
                N = n; S = source; T = sink; maxFlow = 0; minCost = 0;
                adj = new ArrayList[N];
                dist = new int[N];
                for (int i = 0; i < N; i++) {
                    adj[i] = new ArrayList<>();
                }
            }

            boolean bellmanFord(boolean check) {
                Arrays.fill(dist, INF);
                dist[0] = 0;
                for (int i = 0; i < N - 1; i++) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : edgesArray[j]) {
                            if (e.flow == 0) continue;
                            if (dist[j] + e.cost < dist[e.u]) {
                                dist[e.u] = dist[j] + e.cost;
                            }
                        }
                    }
                }
                if (check) {
                    for (int j = 0; j < N; j++) {
                        for (Edge e : edgesArray[j]) {
                            if (e.flow == 0) continue;
                            if (dist[j] + e.cost < dist[e.u]) return false;
                        }
                    }
                }
                return true;
            }

            int[] node, visit, prv, prve, distMin;

            boolean simple() {
                node = new int[N];
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                distMin = new int[N];
                Arrays.fill(distMin, INF);
                node[0] = S;
                distMin[0] = 0;
                int front = 1, back = 0;
                while (front != back) {
                    int u = node[back++];
                    if (back == N) back = 0;
                    visit[u] = 2;
                    for (int i = 0; i < edgesArray[u].length; i++) {
                        Edge e = edgesArray[u][i];
                        if (e.flow == 0) continue;
                        int cdist = distMin[u] + e.cost;
                        if (cdist < distMin[e.u]) {
                            if (visit[e.u] == 0) {
                                node[front++] = e.u;
                                if (front == N) front = 0;
                            } else if (visit[e.u] == 2) {
                                if (--back == -1) back += N;
                                node[back] = e.u;
                            }
                            visit[e.u] = 1;
                            prv[e.u] = u;
                            prve[e.u] = i;
                            distMin[e.u] = cdist;
                        }
                    }
                }
                return visit[T] != 0;
            }

            class Pair {
                int F, S;
                Pair(int f, int s) { F = f; S = s; }
            }

            boolean dijkstra() {
                Arrays.fill(dist, INF);
                Arrays.fill(visit, 0);
                prv = new int[N];
                prve = new int[N];
                PriorityQueue<Pair> pq = new PriorityQueue<>((A, B) -> Integer.compare(A.S, B.S));
                pq.add(new Pair(S, 0));
                dist[S] = 0;
                while (!pq.isEmpty()) {
                    Pair p = pq.poll();
                    if (dist[p.F] < p.S) continue;
                    int u = p.F;
                    visit[u] = 2;
                    for (int i = 0; i < edgesArray[u].length; i++) {
                        Edge e = edgesArray[u][i];
                        if (e.flow == 0) continue;
                        int cdist = p.S + e.cost + dist[u] - dist[e.u];
                        if (cdist < dist[e.u]) {
                            if (visit[e.u] == 2) return false;
                            pq.add(new Pair(e.u, cdist));
                            dist[e.u] = cdist;
                            prv[e.u] = u;
                            prve[e.u] = i;
                            visit[e.u] = 1;
                        }
                    }
                }
                return visit[T] != 0;
            }

            int augment() {
                int p = T, flowMin = INF;
                while (p != S) {
                    int pp = prv[p], pe = prve[p];
                    flowMin = Math.min(flowMin, edgesArray[pp][pe].flow);
                    p = pp;
                }
                p = T;
                while (p != S) {
                    int pp = prv[p], pe = prve[p];
                    edgesArray[pp][pe].flow -= flowMin;
                    int revIdx = edgesArray[pp][pe].rev;
                    edgesArray[p][revIdx].flow += flowMin;
                    p = pp;
                }
                maxFlow += flowMin;
                return flowMin;
            }

            boolean calSimple() {
                while (simple()) {
                    minCost += dist[T] * augment();
                }
                return true;
            }

            void updatePotential() {
                for (int i = 0; i < N; i++) {
                    if (visit[i] != 0) {
                        dist[i] += distMin[i] - dist[S];
                    }
                }
            }

            boolean calWithPotential() {
                while (dijkstra()) {
                    int min = dist[T] + dist[T] - dist[S];
                    minCost += min * augment();
                    updatePotential();
                }
                return true;
            }
        }
        int n, m, k, c, d, a[], f[];
        public void solve(int testNumber, Scanner in, PrintWriter out) {
