                    upperArray[i] -= (upperArray[(int) val] - (idx + 1));
                } else {
                    lowerArray[(int) (n / i / p)] -= (lowerArray[(int) (n / i / p)] - (idx + 1));
                }
            }
            for (int i = limitSize - 1; i >= (long) p * p; --i) {
                lowerArray[i] -= lowerArray[i / p] - (idx + 1);
            }
        }

        long totalCount = 0;
        for (long p : primeNumbers) {
            if (p * p > n) break;
            if (p * p * p <= n && p * p * p > 0) {
                totalCount++;
            }
            if (n / p > p) {
                if (p < limitSize)
                    totalCount += upperArray[(int) p] - lowerArray[(int) p];
                else
                    totalCount += lowerArray[(int) (n / p)] - lowerArray[(int) p];
            }
        }
        return totalCount;
    }

    void debugPrint(Object... args) {
        System.out.println(Arrays.deepToString(args));
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        new Main().startProgram();
    }

    public void startProgram() {
        Scanner scanner = new Scanner(System.in);
        long inputNumber = scanner.nextLong();
        System.out.println(computeAnswer(inputNumber));
    }

    long computeAnswer(long n) {
        int maxLen = (int) 4e5;
        long[] upperPart = new long[maxLen];
        long[] lowerPart = new long[maxLen];
        for (int i = 1; i < maxLen; ++i) {
            lowerPart[i] = i;
            upperPart[i] = n / i;
        }
        boolean[] primeFlags = new boolean[maxLen];
        Arrays.fill(primeFlags, true);
        primeFlags[0] = false;
        primeFlags[1] = false;

        ArrayList<Integer> primes = new ArrayList<>();
        for (int i = 2; i < primeFlags.length; ++i) {
            if (!primeFlags[i]) continue;
            primes.add(i);
            for (int j = i * 2; j < primeFlags.length; j += i) {
                primeFlags[j] = false;
            }
        }

        for (int index = 0; index < primes.size(); ++index) {
            int p = primes.get(index);
            for (int i = 1; i < maxLen && n / i >= (long) p * p; ++i) {
                long val = (long) p * i;
                if (val < maxLen) {
                    upperPart[i] -= (upperPart[(int) val] - (index + 1));
                } else {
                    lowerPart[(int) (n / i / p)] -= (lowerPart[(int) (n / i / p)] - (index + 1));
                }
            }
            for (int i = maxLen - 1; i >= (long) p * p; --i) {
                lowerPart[i] -= lowerPart[i / p] - (index + 1);
            }
        }

        long totalPrimesCount = 0;
        for (long p : primes) {
            if (p * p > n) break;
            if (p * p * p <= n && p * p * p > 0) {
                totalPrimesCount++;
            }
            if (n / p > p) {
                if (p < maxLen)
                    totalPrimesCount += upperPart[(int) p] - lowerPart[(int) p];
                else
                    totalPrimesCount += lowerPart[(int) (n / p)] - lowerPart[(int) p];
            }
        }
        return totalPrimesCount;
    }

    void printDebugInfo(Object... args) {
        System.out.println(Arrays.deepToString(args));
    }
}

