    static class MeisselLehmer2 {
        int[] primes;
        int[] xcums;
        long[] isp;
        int cachelimit;
        LongHashCounterL picache;
        LongHashCounterL phicache;
        boolean cachePhi = false;
        int[][] cumps;
        int[] FP = { 2, 3, 5, 7, 11, 13, 17, 19 };
        int M = FP.length;
        int B = 100;

        public MeisselLehmer2(long n) {
            int s = (int) Math.sqrt(n) * B;
            cachelimit = s;
