            if (delta <= 0) break;
            totalCount += delta;
        }
        for (int p : primes) {
            if ((long) p * p * p <= n) totalCount++;
            else break;
        }
        System.out.println(totalCount);
    }

    static class PrimePiCalculator {
        int[] primes;
        int[] prefixSums;
        long[] primeFlags;
        int limit;
        Map<Long, Long> piCache;
        Map<Long, Long> phiCache;

        public PrimePiCalculator(long n) {
            int s = (int) Math.sqrt(n) * 100;
            limit = s;
            primes = getPrimes(s);
            prefixSums = new int[(s >>> 6) + 1];
            primeFlags = new long[(s >>> 6) + 1];
            for (int p : primes) primeFlags[p >>> 6] |= 1L << p;
            for (int i = 0; i < prefixSums.length - 1; i++)
                prefixSums[i + 1] = prefixSums[i] + Long.bitCount(primeFlags[i]);
            piCache = new HashMap<>();
            phiCache = new HashMap<>();
        }

        public long pi(long x) {
            if (x <= limit) {
                int ix = (int) x;
                return prefixSums[ix >>> 6] + Long.bitCount(primeFlags[ix >>> 6] << (~ix));
            }
            if (piCache.containsKey(x))
                return piCache.get(x);
            int A = (int) pi((long) Math.sqrt(Math.sqrt(x)));
            long res = A + phi(x, A) - P2(x, A) - P3(x, A) - 1;
            piCache.put(x, res);
            return res;
        }

        private long phi(long x, int A) {
            if (A > 0 && A - 1 < primes.length) {
                return prefixSums[A - 1] * (x / primes[A - 1]) + prefixSums[A - 1][(int) (x % primes[A - 1] + 1)];
            }
            if (A > 0 && x <= (long) primes[A - 1] * primes[A - 1]) {
                return pi(x) - A + 1;
            }
            long res = x;
            for (int i = A - 1; i >= 0; i--) {
                res -= phi(x / primes[i], i);
            }
            return res;
        }

        private long P2(long x, int A) {
            int B = (int) pi((long) Math.sqrt(x));
            long sum = 0;
            for (int i = A; i < B; i++) {
                sum += pi(x / primes[i]);
            }
            sum -= (long) (B - A) * (B + A - 1) / 2;
            return sum;
        }

        private long P3(long x, int A) {
            int C = (int) pi(cbrt(x));
            long sum = 0;
            for (int i = A; i < C; i++) {
                long xi = x / primes[i];
                int B = (int) pi((long) Math.sqrt(xi));
                for (int j = i; j < B; j++) {
                    sum += pi(xi / primes[j]) - j;
                }
            }
            return sum;
        }

        private long cbrt(long n) {
            long i = Math.max(0, (long) Math.cbrt(n) - 2);
            while (i * i * i <= n) i++;
            return i - 1;
        }
    }
