        private long phi(long x, int A) {
            if (A > 0 && A - 1 < primes.length) {
                return prefixSum[A - 1] * (x / primes[A - 1]) + prefixSum[A - 1][(int) (x % primes[A - 1] + 1)];
            }
            if (A > 0 && x <= (long) primes[A - 1] * primes[A - 1]) {
                return pi(x) - A + 1;
            }
            long res = x;
            for (int i = A - 1; i >= 0; i--) {
                res -= phi(x / primes[i], i);
            }
            return res;
        }

        private long P2(long x, int A) {
            int B = (int) pi((long) Math.sqrt(x));
            long sum = 0;
            for (int i = A; i < B; i++) {
                sum += pi(x / primes[i]);
            }
            sum -= (long) (B - A) * (B + A - 1) / 2;
            return sum;
        }

        private long P3(long x, int A) {
            int C = (int) pi(cbrt(x));
            long sum = 0;
            for (int i = A; i < C; i++) {
                long xi = x / primes[i];
                int B = (int) pi((long) Math.sqrt(xi));
                for (int j = i; j < B; j++) {
                    sum += pi(xi / primes[j]) - j;
                }
            }
            return sum;
        }

        private long cbrt(long n) {
            long i = Math.max(0, (long) Math.cbrt(n) - 2);
