                    mask[i >> 5] |= 1 << (i & 31);
                for (int j = 0; j < size; j += p) {
                    for (int i = 0; i < p && i + j < size; i++) {
                        isNotPrime[j + i] |= mask[i];
                    }
                }
            }
            int[] magic = { 0, 1, 23, 2, 29, 24, 19, 3, 30, 27, 25, 11, 20, 8, 4, 13, 31, 22, 28, 18, 26, 10, 7, 12, 21, 17,
                    9, 6, 16, 5, 15, 14 };
            int h = n / 2;
            for (int i = 0; i < size; i++) {
                for (int j = ~isNotPrime[i]; j != 0; j &= j - 1) {
                    int pIndex = i << 5 | magic[(j & -j) * 0x076be629 >>> 27];
                    int p = 2 * pIndex + 3;
                    if (p > n) break;
                    result[index++] = p;
                    if ((long) p * p > n) continue;
                    for (int q = (p * p - 3) / 2; q <= h; q += p)
                        isNotPrime[q >> 5] |= 1 << q;
                }
            }
            return Arrays.copyOf(result, index);
        }

        private static class LongHashMap {
            public long[] keys;
            public long[] values;
            private int size = 0;
            private int capacity = 4;
            private static final long NG = Long.MIN_VALUE;

            public LongHashMap() {
                keys = new long[capacity];
                values = new long[capacity];
                Arrays.fill(keys, NG);
            }

            public boolean containsKey(long key) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != NG) {
                    if (keys[pos] == key) return true;
                    pos = (pos + 1) & (capacity - 1);
                }
                return false;
            }

            public long get(long key) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != NG) {
                    if (keys[pos] == key) return values[pos];
                    pos = (pos + 1) & (capacity - 1);
                }
                return NG;
            }

            public void put(long key, long value) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != NG) {
                    if (keys[pos] == key) {
                        values[pos] = value;
                        return;
                    }
                    pos = (pos + 1) & (capacity - 1);
                }
                if (size == capacity) resize();
                keys[pos] = key;
                values[pos] = value;
                size++;
            }

            private void resize() {
                capacity <<= 1;
                long[] newKeys = new long[capacity];
                long[] newValues = new long[capacity];
                Arrays.fill(newKeys, NG);
                for (int i = 0; i < keys.length; i++) {
                    if (keys[i] != NG) {
                        int pos = hash(keys[i]) & (capacity - 1);
                        while (newKeys[pos] != NG) pos = (pos + 1) & (capacity - 1);
                        newKeys[pos] = keys[i];
                        newValues[pos] = values[i];
                    }
                }
                keys = newKeys;
                values = newValues;
            }

            private int hash(long x) {
                x ^= x >>> 33;
                x *= 0xff51afd7ed558ccdL;
                x ^= x >>> 33;
                x *= 0xc4ceb9fe1a85ec53L;
                x ^= x >>> 33;
                return (int) x;
            }
        }
    }

