                int pIndex = i << 5 | magic[(j & -j) * 0x076be629 >>> 27];
                int p = 2 * pIndex + 3;
                if (p > n) break;
                result[index++] = p;
                if ((long) p * p > n) continue;
                for (int q = (p * p - 3) / 2; q <= halfN; q += p)
                    isNotPrime[q >> 5] |= 1 << q;
            }
        }
        return Arrays.copyOf(result, index);
    }

