            int C = (int) pi(cbrt(x));
            long ret = 0;
            for (int i = A; i < C; i++) {
                long xi = x / primes[i];
                int B = (int) pi(sqrt(xi));
                for (int j = i; j < B; j++) {
                    ret += pi(xi / primes[j]) - j;
                }
            }
            return ret;
        }

