        private static class LongHashMap {
            public long[] keys;
            public long[] values;
            private int size = 0;
            private int capacity = 16;
            private static final long EMPTY = Long.MIN_VALUE;

            public LongHashMap() {
                keys = new long[capacity];
                values = new long[capacity];
                Arrays.fill(keys, EMPTY);
            }

            public boolean containsKey(long key) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != EMPTY) {
                    if (keys[pos] == key) return true;
                    pos = (pos + 1) & (capacity - 1);
                }
                return false;
            }

            public long get(long key) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != EMPTY) {
                    if (keys[pos] == key) return values[pos];
                    pos = (pos + 1) & (capacity - 1);
                }
                return 0;
            }

            public void put(long key, long value) {
                int pos = hash(key) & (capacity - 1);
                while (keys[pos] != EMPTY) {
                    if (keys[pos] == key) {
                        values[pos] = value;
                        return;
                    }
                    pos = (pos + 1) & (capacity - 1);
                }
                if (size >= capacity * 0.75) resize();
                keys[pos] = key;
                values[pos] = value;
                size++;
            }

            private void resize() {
                capacity <<= 1;
                long[] newKeys = new long[capacity];
                long[] newValues = new long[capacity];
                Arrays.fill(newKeys, EMPTY);
                for (int i = 0; i < keys.length; i++) {
                    if (keys[i] != EMPTY) {
                        int pos = hash(keys[i]) & (capacity - 1);
                        while (newKeys[pos] != EMPTY) pos = (pos + 1) & (capacity - 1);
                        newKeys[pos] = keys[i];
                        newValues[pos] = values[i];
                    }
                }
                keys = newKeys;
                values = newValues;
            }

            private int hash(long key) {
                key ^= (key >>> 33);
                key *= 0xff51afd7ed558ccdL;
                key ^= (key >>> 33);
                key *= 0xc4ceb9fe1a85ec53L;
                key ^= (key >>> 33);
                return (int) key;
            }
        }
    }

