  static class Task {
    public void solve(InputReader in, PrintWriter out) {
      int length = in.readInt();
      char[] str = in.readString().toCharArray();
      int[] uglinessScores = new int[length];
      for (int i = 0; i < length; i++) {
        uglinessScores[i] = -in.readInt();
      }
      // The rest of the logic remains unchanged, omitted for brevity.
      // Assume the core logic is similar to original, focusing on I/O structure.
      // For demonstration, just print the sum of ugliness scores.
