    static class TaskF {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            String s = in.nextString();
            int[] a = new int[n];
            int[] cnt = new int[26];
            for (int i = 0; i < n; ++i) {
                a[i] = in.nextInt();
                cnt[(int) s.charAt(i) - 'a']++;
            }
            Graph g = new Graph(n + 100);
            int source = n + 100 - 2, target = source + 1;
            for (int i = 0; i * 2 < n; ++i) g.addFlowWeightedEdge(i, target, 0, 2);
            for (int i = 0; i < 26; ++i) {
                g.addFlowWeightedEdge(source, i + n, 0, cnt[i]);
                for (int j = 0; j * 2 < n; ++j) {
                    if (s.charAt(j) == s.charAt(n - j - 1)) {
                        int w = 0;
                        if (s.charAt(j) == i + 'a') w = -Math.max(a[j], a[n - j - 1]);
                        g.addFlowWeightedEdge(i + n, j, w, 1);
                    } else {
                        int w = 0;
                        if (s.charAt(j) == i + 'a') w -= a[j];
                        if (s.charAt(n - j - 1) == i + 'a') w -= a[n - j - 1];
                        g.addFlowWeightedEdge(i + n, j, w, 1);
                    }
                }
            }
            MinCostFlow mcmf = new MinCostFlow(g, source, target, true);
            out.println(-mcmf.minCostMaxFlow().first);

        }

    }

