import java.util.*;

import static java.util.Arrays.stream;
import static java.util.stream.Collectors.toMap;

public class Main {
    static int n;
    static char[] chars;
    static int[] vals;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        n = sc.nextInt();
        sc.nextLine();
        String s = sc.nextLine().trim();
        chars = s.toCharArray();

        vals = new int[n];
        for (int i = 0; i < n; i ++) {
            vals[i] = sc.nextInt();
        }
        sc.nextLine();

        List<Char> wrongChars = new ArrayList<>();
        List<Char> chars1 = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            if (vals[i] > vals[n - i - 1]) {
                swap(i);
            }

            Char chr = new Char(chars[i], vals[i], i);
            if (chars[i] == chars[n - i - 1]) {
                wrongChars.add(chr);
            }
            chars1.add(chr);
        }
        chars1.sort(Comparator.comparing(c -> c.val));

        int diff = 0;
//        int[] vals1 = Arrays.copyOf(vals, n/2);
        if (!isAntiPalindrome(chars)) {
            if (wrongChars.size() == 1) {
                Char wrongChar = wrongChars.get(0);
                for (int i = 0; i < n/2; i++) {
                    Char chr = chars1.get(i);
                    if (chr.chr != wrongChar.chr && chars[n - chr.idx - 1] != wrongChar.chr) {
                        diff = wrongChar.val + chr.val;
                        break;
                    }
                }
            } else if (wrongChars.size() > 1) {
                Map<Character, Integer> map = wrongChars.stream().collect(toMap(n -> n.chr, n -> 1, (a, b) -> a+1, TreeMap::new));
                Map.Entry<Character, Integer> max = map.entrySet().stream().max(Comparator.comparing(Map.Entry::getValue)).get();
                List<Char> append = new ArrayList<>();
                while (max.getValue() * 2 > wrongChars.size() + append.size()) {
                    Character maxChar = max.getKey();
                    for (int i = 0; i < n/2; i++) {
                        Char chr = chars1.get(i);
                        if (chr.chr != maxChar && chars[n - chr.idx - 1] != maxChar && !wrongChars.contains(chr) && !append.contains(chr)) {
                            append.add(chr);
                            break;
                        }
                    }
                }
                diff = wrongChars.stream().mapToInt(chr -> chr.val).sum() + append.stream().mapToInt(chr -> chr.val).sum();
            }
        }

        int sum = stream(vals).sum();
        System.out.println(sum - diff);
    }

    private static void swap(int i) {
        char tmp = chars[i];
        chars[i] = chars[n - i - 1];
        chars[n - i - 1] = tmp;

        int tmpVal = vals[i];
        vals[i] = vals[n - i - 1];
        vals[n - i - 1] = tmpVal;
    }

    private static void swap(int i, int j) {
        char tmp = chars[i];
        chars[i] = chars[j];
        chars[j] = tmp;

        int tmpVal = vals[i];
        vals[i] = vals[n - i - 1];
        vals[n - i - 1] = tmpVal;
    }

    private static boolean isAntiPalindrome(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < n/2; i++) {
            if (chars[i] == chars[n - i - 1]) {
                return false;
            }
        }
        return true;
    }

    static class Char {
        char chr;
        int val;
        int idx;

        Char(char chr, int val, int idx) {
            this.chr = chr;
            this.val = val;
            this.idx = idx;
        }

        @Override
        public String toString() {
            return "Char{" +
                    "chr=" + chr +
                    ", val=" + val +
                    ", idx=" + idx +
                    '}';
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        scanner.nextLine();
        String line = scanner.nextLine().trim();
        char[] characters = line.toCharArray();

        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = scanner.nextInt();
        }
        scanner.nextLine();

        List<CharacterInfo> mismatchedChars = new ArrayList<>();
        List<CharacterInfo> charList = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            if (values[i] > values[n - i - 1]) {
                swap(characters, values, i);
            }
            CharacterInfo ci = new CharacterInfo(characters[i], values[i], i);
            if (characters[i] == characters[n - i - 1]) {
                mismatchedChars.add(ci);
            }
            charList.add(ci);
        }
        charList.sort(Comparator.comparing(c -> c.val));

        int totalDiff = 0;
        if (!isAntiPalindrome(characters)) {
            if (mismatchedChars.size() == 1) {
                CharacterInfo wrongChar = mismatchedChars.get(0);
                for (CharacterInfo ci : charList) {
                    if (ci.chr != wrongChar.chr && characters[n - ci.idx - 1] != wrongChar.chr) {
                        totalDiff = wrongChar.val + ci.val;
                        break;
                    }
                }
            } else if (mismatchedChars.size() > 1) {
                Map<Character, Integer> countMap = new HashMap<>();
                for (CharacterInfo ci : mismatchedChars) {
                    countMap.put(ci.chr, countMap.getOrDefault(ci.chr, 0) + 1);
                }
                int maxCount = Collections.max(countMap.values());
                List<CharacterInfo> appendList = new ArrayList<>();
                while (maxCount * 2 > mismatchedChars.size() + appendList.size()) {
                    char maxChar = Collections.max(countMap.entrySet(), Map.Entry.comparingByValue()).getKey();
                    for (CharacterInfo ci : charList) {
                        if (ci.chr != maxChar && characters[n - ci.idx - 1] != maxChar && !mismatchedChars.contains(ci) && !appendList.contains(ci)) {
                            appendList.add(ci);
                            break;
                        }
                    }
                }
                totalDiff = mismatchedChars.stream().mapToInt(c -> c.val).sum() + appendList.stream().mapToInt(c -> c.val).sum();
            }
        }
        int sumValues = Arrays.stream(values).sum();
        System.out.println(sumValues - totalDiff);
    }

    private static void swap(char[] chars, int[] vals, int i) {
        char tempChar = chars[i];
        chars[i] = chars[chars.length - i - 1];
        chars[chars.length - i - 1] = tempChar;

        int tempVal = vals[i];
        vals[i] = vals[vals.length - i - 1];
        vals[vals.length - i - 1] = tempVal;
    }

    private static boolean isAntiPalindrome(char[] chars) {
        int len = chars.length;
        for (int i = 0; i < len / 2; i++) {
            if (chars[i] == chars[len - i - 1]) {
                return false;
            }
        }
        return true;
    }

    static class CharacterInfo {
        char chr;
        int val;
        int idx;

        CharacterInfo(char chr, int val, int idx) {
            this.chr = chr;
            this.val = val;
            this.idx = idx;
        }
    }
}

