        PrintWriter pw = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine());
        char[] s = br.readLine().toCharArray();

        int[] freq = new int[26];
        for (char c : s) freq[c - 'a']++;
        for (int count : freq) {
            if (count > n / 2) {
                pw.println(-1);
                pw.close();
                return;
            }
        }

        int[] a = new int[n];
        String[] parts = br.readLine().split(" ");
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(parts[i]);

        for (int i = 0; i < n / 2; i++) {
            if (a[i] > a[n - 1 - i]) {
                int tempA = a[i];
                a[i] = a[n - 1 - i];
                a[n - 1 - i] = tempA;

                char tempC = s[i];
                s[i] = s[n - 1 - i];
                s[n - 1 - i] = tempC;
            }
        }

        List<Edge> edges = new ArrayList<>();
        int src = n, sink = n + 1;
        for (int i = 0; i < n / 2; i++) {
            edges.add(new Edge(src, i, 1, 0));
            edges.add(new Edge(n - 1 - i, sink, 1, 0));
            for (int j = 0; j < n / 2; j++) {
                if (s[i] != s[n - 1 - j]) {
                    edges.add(new Edge(i, n - 1 - j, 1, i == j ? 0 : a[i]));
                }
            }
        }

        long totalSum = 0;
        for (int val : a) totalSum += val;
        long minCost = solveMinCostFlow(compileWD(sink + 1, edges), src, sink, n);
        pw.println(totalSum - minCost);
        pw.close();
    }

    static class Edge {
        int from, to, capacity, cost, flow;
        Edge complement;

        public Edge(int from, int to, int capacity, int cost) {
            this.from = from;
            this.to = to;
            this.capacity = capacity;
            this.cost = cost;
            this.flow = 0;
        }
    }

    static Edge[][] compileWD(int n, List<Edge> edges) {
        List<Edge> allEdges = new ArrayList<>(edges);
        for (int i = allEdges.size() - 1; i >= 0; i--) {
            Edge e = allEdges.get(i);
            Edge rev = new Edge(e.to, e.from, e.capacity, -e.cost);
            rev.flow = e.capacity;
            e.complement = rev;
            rev.complement = e;
            allEdges.add(rev);
        }
        int[] p = new int[n];
        for (Edge e : allEdges) p[e.from]++;
        Edge[][] g = new Edge[n][];
        for (int i = 0; i < n; i++) g[i] = new Edge[p[i]];
        int[] idx = new int[n];
        for (Edge e : allEdges) {
            g[e.from][idx[e.from]++] = e;
        }
        return g;
    }

    static long solveMinCostFlow(Edge[][] g, int s, int t, int totalFlow) {
        int n = g.length;
        long minCost = 0;
        int[] potential = new int[n];
        int[] dist = new int[n];
        Edge[] parent = new Edge[n];

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        while (totalFlow > 0) {
            Arrays.fill(dist, Integer.MAX_VALUE / 2);
            dist[s] = 0;
            pq.clear();
            pq.offer(new int[]{s, 0});
            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int u = cur[0], d = cur[1];
                if (d > dist[u]) continue;
                for (Edge e : g[u]) {
                    if (e.capacity - e.flow > 0) {
                        int nd = d + e.cost + potential[u] - potential[e.to];
                        if (dist[e.to] > nd) {
                            dist[e.to] = nd;
                            parent[e.to] = e;
                            pq.offer(new int[]{e.to, nd});
                        }
                    }
                }
            }
            if (parent[t] == null) break;
            int flow = totalFlow;
            for (Edge e = parent[t]; e != null; e = parent[e.from]) {
                flow = Math.min(flow, e.capacity - e.flow);
            }
            long cost = 0;
            for (Edge e = parent[t]; e != null; e = parent[e.from]) {
                e.flow += flow;
                e.complement.flow -= flow;
                cost += (long) e.cost * flow;
            }
            minCost += cost;
            totalFlow -= flow;
            for (int i = 0; i < n; i++) {
                if (dist[i] < Integer.MAX_VALUE / 2) {
                    potential[i] += dist[i];
                }
            }
        }
        return minCost;
    }
}

