					if (cur == aSize) {
						break;
					}
					int pos = aData[cur];
					if (pos >= aTo) {
						break;
					}
					res.push(pos - bShift);
					++cur;
				}
				if (i == bSize - 1) {
					break;
				}
				res.push(bTo);
			}
			putList(a);
			putList(b);
		}
		return res;
	}

