			if (s < m) {
				s += ct;
				if (s >= n) {
					s -= n;
				}
			} else {
				s -= ct;
				if (s < 0) {
					s += n;
				}
			}
		}
		long cycles = t / n;
		if (cycles > 0) {
			IntList cycleSolve = solve(0, n);
