        l -= (l / cycleSum) * cycleSum;
        r = Math.min(r, cycleSum * 3);
        r -= (r / cycleSum) * cycleSum;

        int[] pattern = new int[r];
        for (int i = 0; i < r; i++) {
            pattern[i] = i;
        }

        for (int i = a; i < r; i++) {
            if (i % cycleSum < a) {
                Set<Integer> usedSet = new HashSet<>();
                for (int j = i - 1; j >= i - a && j >= 0; j--) {
                    usedSet.add(pattern[j]);
                }
                for (int j = 0, k = 0; i % cycleSum != a && i < r; i++, j++) {
                    while (usedSet.contains(j)) j++;
                    usedSet.add(j);
                    pattern[i] = j;
                }
            } else {
                pattern[i] = pattern[i - 1];
            }
        }

        Set<Integer> distinctSet = new HashSet<>();
        for (int i = l; i < r; i++) {
            distinctSet.add(pattern[i]);
        }
        int minDistinct = distinctSet.size();

        for (int i = a; i < a + b && i < r; i++) {
            pattern[i] = pattern[b];
        }

        for (int i = a + b; i < r; i++) {
            if (i % cycleSum < a) {
                Set<Integer> usedSet = new HashSet<>();
                for (int j = i - 1; j >= i - a && j >= 0; j--) {
                    usedSet.add(pattern[j]);
                }
                for (int j = 0, k = 0; i % cycleSum != a && i < r; i++, j++) {
                    while (usedSet.contains(j)) j++;
                    usedSet.add(j);
                    pattern[i] = j;
                }
            } else {
                pattern[i] = pattern[i - 1];
            }
        }

        distinctSet.clear();
        for (int i = l; i < r; i++) {
            distinctSet.add(pattern[i]);
        }
        minDistinct = Math.min(minDistinct, distinctSet.size());

