		long l = Long.parseLong(inputData.nextToken());
		long r = Long.parseLong(inputData.nextToken());

		if (r - l + 1 >= 2 * (a + b)) {
			if (a <= b) {
				System.out.println(a + 1);
			} else {
				System.out.println(2 * a - b);
			}
			return;
		}

		StringBuilder cString = new StringBuilder();
		for (int i = 0; i < a; i++) {
			cString.append((char) ('a' + i));
		}

