        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int a = Integer.parseInt(input[0]);
        int b = Integer.parseInt(input[1]);
        int l = Integer.parseInt(input[2]);
        int r = Integer.parseInt(input[3]);

        System.out.println(solve(a, b, l, r));
    }

    static int solve(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b))
            return (a <= b) ? a + 1 : (2 * a - b);

        int[] pattern = new int[3 * (a + b) + 1];

        int lastVal = 0;
        for (int i = 1; i <= a; i++) {
            pattern[i] = i;
            lastVal = i;
        }

        for (int i = a + 1; i <= a + b; i++) {
            pattern[i] = lastVal;
        }

        for (int i = a + b + 1; i <= a + b + a; i++) {
            int count = 1;
            while (contains(pattern, count, a + b - a + 1, i - 1))
                count++;
            pattern[i] = count;
            lastVal = count;
        }

        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            pattern[i] = lastVal;
        }

        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            pattern[i] = pattern[i - (a + b)];
        }

        int[] counts = new int[25];
        int startIdx = l % (a + b);
        if (startIdx == 0) startIdx += a + b;
        int endIdx = r - l + startIdx;
        if (endIdx < startIdx) endIdx += a + b;

        for (int i = startIdx; i <= endIdx; i++) {
            counts[pattern[i]] = 1;
        }

        int total = 0;
        for (int i = 1; i <= 24; i++) {
            total += counts[i];
        }
        return total;
    }

    static boolean contains(int[] arr, int val, int start, int end) {
        for (int i = start; i <= end; i++) {
            if (arr[i] == val)
                return true;
        }
        return false;
    }
}

